window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id": "yy-8001", "module": "yanyu", "prompt": "基层治理是国家治理的基石，治理重心下移、资源下沉，就是要让基层有______的权力和资源，把事情办实办好。填入画横线处最恰当的一项是：", "options": ["相匹配", "同等级", "共进退", "相一致"], "answer": 0, "explanation": "「相匹配」强调权力、资源与承担的事务相互对应、彼此适配，最符合治理语境下权责资源对等的要求。「相一致」多指意见、看法相同，不与「权力和资源」搭配；「同等级」强调级别高低，语义偏离；「共进退」指行动上步调统一，与句意无关。故选A", "diff": 2},{"id": "yy-8002", "module": "yanyu", "prompt": "科技创新不能______，必须打通从基础研究到产业应用的链条，让成果真正落地转化。填入画横线处最恰当的一项是：", "options": ["闭门造车", "随波逐流", "坐享其成", "纸上谈兵"], "answer": 3, "explanation": "「纸上谈兵」比喻空谈理论、不能解决实际问题，与后文「打通链条、落地转化」形成呼应，强调不能只停留在研究层面。「闭门造车」侧重脱离实际、不与外界交流，虽也含贬义但重点在「封闭」而非「空谈」；「坐享其成」指不劳而获；「随波逐流」指没有主见，均与文意不符。故选D", "diff": 2},{"id": "yy-8003", "module": "yanyu", "prompt": "文化遗产保护不是把老物件锁进库房，而是要______，让收藏在博物馆里的文物、陈列在广阔大地上的遗产都活起来。填入画横线处最恰当的一项是：", "options": ["古为今用", "修旧如旧", "推陈出新", "原封不动"], "answer": 0, "explanation": "「古为今用」指批判地继承古代文化遗产，使之为今天服务，与后文「活起来」的表述高度契合。「推陈出新」强调去掉旧的创造新的，侧重「创新」而非「利用」，程度过重；「原封不动」与文意相悖；「修旧如旧」只是文物保护的一种技术原则，未体现「利用」之意。故选A", "diff": 2},{"id": "yy-8004", "module": "yanyu", "prompt": "生态保护红线一旦划定，就具有______的约束力，任何地方、任何人都不得逾越。填入画横线处最恰当的一项是：", "options": ["强制性", "根本性", "约束性", "威慑性"], "answer": 0, "explanation": "「强制性」指凭借法律或制度力量必须执行、不容违反，与「不得逾越」的刚性要求搭配最紧。「威慑性」侧重以气势使人畏惧，多用于军事、外交语境；「约束性」与「约束力」语义重复；「根本性」强调地位重要，与「不得逾越」的执行力度无关。故选A", "diff": 2},{"id": "yy-8005", "module": "yanyu", "prompt": "发展县域经济不能______，各地要立足自身资源禀赋，宜农则农、宜工则工、宜商则商。填入画横线处最恰当的一项是：", "options": ["生搬硬套", "千篇一律", "削足适履", "东施效颦"], "answer": 1, "explanation": "「千篇一律」指办事按一个样子、毫无变化，与后文「立足自身禀赋、分类施策」形成对照，强调不能一个模式。「生搬硬套」指机械模仿别人经验，侧重「模仿」动作；「东施效颦」含盲目模仿反而出丑的讽刺意味，语体过重；「削足适履」指迁就现成条件硬凑，均不如「千篇一律」贴合「模式化发展」的批评。故选B", "diff": 2},{"id": "yy-8006", "module": "yanyu", "prompt": "调查研究是谋事之基、成事之道，只有______地深入一线，才能听到真话、看到实情。填入画横线处最恰当的一项是：", "options": ["身临其境", "身体力行", "脚踏实地", "设身处地"], "answer": 2, "explanation": "「脚踏实地」形容做事踏实认真、不浮夸，与「深入一线、听真话看实情」的求实要求一致。「身临其境」指亲自到了那个环境，多形容感受真切，属描述性而非态度性词语；「设身处地」指替别人着想，对象错位；「身体力行」指亲身体验努力实行，多用于倡导某种做法，与语境略有出入。故选C", "diff": 2},{"id": "yy-8007", "module": "yanyu", "prompt": "把论文写在祖国大地上，科研人员就要走出实验室，______田间地头，把研究做到生产一线。填入画横线处最恰当的一项是：", "options": ["坐镇", "扎根", "盘踞", "驻扎"], "answer": 1, "explanation": "「扎根」比喻深入到某个环境中长期立足，感情色彩积极，与「田间地头」「生产一线」搭配自然。「驻扎」多指军队或团体驻留，语体不合；「盘踞」含贬义，指非法占据；「坐镇」指亲自坐守要地指挥，多用于领导、专家，与科研人员下沉一线的语境不符。故选B", "diff": 2},{"id": "yy-8008", "module": "yanyu", "prompt": "城市更新不能大拆大建，要在______中留住城市记忆，让老街巷焕发新活力。填入画横线处最恰当的一项是：", "options": ["改造升级", "精雕细琢", "推倒重来", "修旧利废"], "answer": 0, "explanation": "「改造升级」指在原有基础上进行更新提升，与「留住记忆、焕发活力」的渐进式更新思路一致。「修旧利废」侧重利用旧物、厉行节约，语义偏窄；「推倒重来」与「不能大拆大建」直接矛盾；「精雕细琢」强调细致打磨，未体现「更新」之意。故选A", "diff": 2},{"id": "yy-8009", "module": "yanyu", "prompt": "乡村振兴，关键在人。只有让懂农业、爱农村的人才______，乡村才能有源源不断的发展动能。填入画横线处最恰当的一项是：", "options": ["各显神通", "纷至沓来", "留得住、干得好", "脱颖而出"], "answer": 2, "explanation": "语境强调人才既要「留下来」又要「发挥作用」，「留得住、干得好」完整覆盖这两层意思，且口语化表述与「关键在人」的务实语风一致。「脱颖而出」指才能显露，未含「留下」之意；「各显神通」只讲发挥本领；「纷至沓来」只讲人才到来，均不全面。故选C", "diff": 2},{"id": "yy-8010", "module": "yanyu", "prompt": "优化营商环境没有完成时，只有进行时，必须______、久久为功。填入画横线处最恰当的一项是：", "options": ["持之以恒", "一劳永逸", "立竿见影", "水滴石穿"], "answer": 0, "explanation": "「持之以恒」指长久坚持下去，与「久久为功」并列连贯，共同强调长期性。「一劳永逸」与「只有进行时」矛盾；「立竿见影」强调见效快，与「长期坚持」的语义方向相反；「水滴石穿」虽含坚持之意，但侧重微小力量积累成效，与「优化营商环境」的持续作为语境不如「持之以恒」贴切。故选A", "diff": 2},{"id": "yy-8011", "module": "yanyu", "prompt": "数字技术为乡村治理______了新路径，让数据多跑路、群众少跑腿成为现实。填入画横线处最恰当的一项是：", "options": ["开启", "开辟", "开拓", "开放"], "answer": 1, "explanation": "「开辟」指打开、创立新道路或新局面，与「新路径」搭配最规范。「开拓」多与「市场、疆域」搭配；「开放」指解除限制、允许进入，与「路径」不搭；「开启」多与「序幕、时代」搭配，强调开始一个过程，不如「开辟」强调「创立」之意准确。故选B", "diff": 2},{"id": "yy-8012", "module": "yanyu", "prompt": "面对复杂多变的外部环境，我们既要______风险挑战，也要看到长期向好的基本面没有变。填入画横线处最恰当的一项是：", "options": ["正视", "正视与回避", "重视", "藐视"], "answer": 0, "explanation": "「正视」指用认真严肃的态度对待、不回避，与后文「也要看到基本面」的辩证表述衔接自然。「重视」程度不足，缺少「直面」的意味；「藐视」指轻视，态度不严谨；「正视与回避」本身矛盾，不合语法逻辑。故选A", "diff": 2},{"id": "yy-8013", "module": "yanyu", "prompt": "一些地方在推进数字化政务时______，只顾建平台、堆系统，忽视了群众实际使用体验。填入画横线处最恰当的一项是：", "options": ["贪大求快", "好高骛远", "急功近利", "重表轻里"], "answer": 3, "explanation": "「重表轻里」准确概括「重建设形式、轻实际效用」的问题，与「只顾建平台、堆系统，忽视使用体验」一一对应。「贪大求快」强调贪图规模、追求速度；「好高骛远」指不切实际地追求过高目标；「急功近利」指急于求成、贪图眼前利益，均未点出「表里失衡」这一要害。故选D", "diff": 2},{"id": "yy-8014", "module": "yanyu", "prompt": "中华优秀传统文化是中华民族的根和魂，必须______地传承下去。填入画横线处最恰当的一项是：", "options": ["原原本本", "原汁原味", "有条不紊", "不折不扣"], "answer": 0, "explanation": "「原原本本」指从头到尾、照原样完整地，与「传承」搭配，强调文化的完整性与真实性。「原汁原味」多形容食物或作品保持原始风味，语体偏生活化；「不折不扣」多与「执行、落实」搭配；「有条不紊」形容有条理、不紊乱，与传承的完整性无关。故选A", "diff": 2},{"id": "yy-8015", "module": "yanyu", "prompt": "粮食安全是「国之大者」，18亿亩耕地红线必须______，寸土不让。填入画横线处最恰当的一项是：", "options": ["严于律己", "严惩不贷", "严防死守", "严阵以待"], "answer": 2, "explanation": "「严防死守」指严密防守、坚决守住，与「红线」「寸土不让」的守卫语境高度契合。「严阵以待」指做好战斗准备等待来敌，强调「待」而非「守」；「严惩不贷」指严厉惩罚不予宽恕，对象是人而非耕地；「严于律己」指对自己要求严格，语义完全不合。故选C", "diff": 2},{"id": "yy-8016", "module": "yanyu", "prompt": "青年人要______，把个人理想融入国家发展伟业，在平凡岗位上创造不平凡的业绩。填入画横线处最恰当的一项是：", "options": ["好高骛远", "雄心勃勃", "志存高远", "高瞻远瞩"], "answer": 2, "explanation": "「志存高远」指立志远大，是褒义词，与「把个人理想融入国家发展」的语境一致。「高瞻远瞩」形容眼光远大，多用于形容领导者或战略眼光；「雄心勃勃」形容野心很大，感情色彩偏中性甚至含贬义；「好高骛远」是贬义词，指不切实际地追求过高目标。故选C", "diff": 2},{"id": "yy-8017", "module": "yanyu", "prompt": "政务服务改革要以群众满意为标尺，______群众反映强烈的堵点难点，一项一项整改到位。填入画横线处最恰当的一项是：", "options": ["盯住", "瞄准", "对准", "聚焦"], "answer": 3, "explanation": "「聚焦」比喻把注意力集中到某一点上，与「堵点难点」搭配是政务语境的规范用法。「瞄准」「对准」偏具体动作，语体过于形象；「盯住」口语化且只强调持续注视，未体现「集中力量解决」之意。故选D", "diff": 2},{"id": "yy-8018", "module": "yanyu", "prompt": "历史是最好的教科书，学习党史要______，从党的百年奋斗中汲取智慧和力量。填入画横线处最恰当的一项是：", "options": ["耳濡目染", "学思践悟", "温故知新", "潜移默化"], "answer": 1, "explanation": "「学思践悟」指学习、思考、实践、领悟四个环节贯通，是对学习党史的完整要求，与「汲取智慧和力量」衔接紧密。「耳濡目染」「潜移默化」都强调不知不觉受到影响，主体多是被动接受；「温故知新」侧重复习旧知识获得新理解，程度和维度都不够。故选B", "diff": 2},{"id": "yy-8019", "module": "yanyu", "prompt": "民营经济是推进中国式现代化的生力军，要______民营企业发展信心，落实好各项支持政策。填入画横线处最恰当的一项是：", "options": ["提高", "增强", "提升", "提振"], "answer": 3, "explanation": "「提振信心」是规范搭配，「提振」含振作、鼓舞之意，比「提高」「增强」更契合信心的动态恢复。「提高」多与水平、质量搭配；「增强」多与能力、意识搭配；「提升」多与层次、品质搭配，与「信心」的搭配力度都不如「提振」精准。故选D", "diff": 2},{"id": "yy-8020", "module": "yanyu", "prompt": "安全生产责任重于泰山，必须______，任何时候都不能有丝毫麻痹大意。填入画横线处最恰当的一项是：", "options": ["警钟长鸣", "居安思危", "防微杜渐", "未雨绸缪"], "answer": 0, "explanation": "「警钟长鸣」比喻时刻保持警惕，与「不能麻痹大意」形成直接呼应，是安全生产语境的惯用语。「防微杜渐」指在苗头出现时加以制止，强调「早处置」；「未雨绸缪」强调「早准备」；「居安思危」强调「有忧患意识」，三者都缺少「时刻警惕」这层持续状态。故选A", "diff": 2},{"id": "yy-8021", "module": "yanyu", "prompt": "这段文字主要说明：人工智能正在重塑就业结构。一方面，重复性、程序化的岗位加速被替代；另一方面，算法训练师、数据标注员、提示词工程师等新职业不断涌现。技术进步从来都是「双刃剑」，与其担忧被机器取代，不如主动拥抱变化，提升与智能时代相匹配的技能。", "options": ["技术进步必然导致结构性失业", "新技术条件下劳动者应主动提升技能", "人工智能将大规模减少就业岗位", "新职业涌现缓解了就业压力"], "answer": 1, "explanation": "文段先讲人工智能对就业结构的双重影响，末句用「与其……不如……」点明落脚点：主动拥抱变化、提升匹配技能。B项正是这一主旨。A项只概括了「替代」一面且「大规模减少」表述绝对；C项「缓解就业压力」文中未提；D项「必然导致」过于绝对，且文段重点是应对之道而非后果判断。故选B", "diff": 2},{"id": "yy-8022", "module": "yanyu", "prompt": "这段文字意在强调：传统村落是农耕文明的活化石，承载着乡愁记忆与地域文化。然而随着城镇化推进，不少传统村落面临空心化、老龄化困境，一些具有保护价值的古民居因无人居住而年久失修。保护传统村落，不能只靠情怀呼吁，更要建立长效投入机制，让村民在保护中受益，才能形成保护的内生动力。", "options": ["城镇化是传统村落衰落的根源", "传统村落保护形势严峻", "传统村落保护应建立让村民受益的长效机制", "古民居修缮需要大量资金投入"], "answer": 2, "explanation": "文段先介绍传统村落的价值与困境，末句以「不能只靠……更要……」提出对策：建立长效投入机制、让村民受益、形成内生动力。C项是对这一对策的准确概括。A项是问题背景而非意图；B项「根源」的说法文中未确立，且文段重点不在归因；D项只是对策的一个侧面。故选C", "diff": 2},{"id": "yy-8023", "module": "yanyu", "prompt": "这段文字主要说明：近年来，「博物馆热」持续升温，越来越多的年轻人走进博物馆，把观展当作一种生活方式。一些博物馆推出夜游、剧本导览、文创雪糕等新玩法，让文物以更亲切的方式走近公众。不过，热度之下也要冷思考：博物馆的核心使命是收藏、研究与教育，创新形式不能喧宾夺主，更不能为了流量而娱乐化、庸俗化。", "options": ["「博物馆热」带动了文创产业发展", "博物馆教育功能正在逐步弱化", "博物馆应警惕过度娱乐化倾向", "博物馆创新形式吸引了年轻观众"], "answer": 2, "explanation": "文段先描述「博物馆热」及创新形式，转折词「不过」之后是重点：创新不能喧宾夺主、不能娱乐化庸俗化。C项准确概括了这一提醒。A项是转折前的内容；B项「文创产业」文中未涉及；D项「教育功能弱化」是无中生有的推断。故选C", "diff": 2},{"id": "yy-8024", "module": "yanyu", "prompt": "这段文字意在强调：盐碱地被称为「沉睡」的耕地资源。我国有约15亿亩盐碱地，若能唤醒其中一部分用于种植耐盐碱作物，将有效拓展农业生产空间。近年来，科学家通过培育耐盐碱水稻、改良土壤结构等方式，让部分盐碱地变成了稳产田。这背后是育种技术、土壤改良技术的协同突破，也离不开政策扶持与长期投入。", "options": ["我国盐碱地资源丰富、潜力巨大", "耐盐碱作物育种取得重大进展", "唤醒盐碱地需要技术突破与长期投入并举", "盐碱地改良的技术路径已经成熟"], "answer": 2, "explanation": "文段先介绍盐碱地的价值，再举例说明改良成效，末句用「离不开……也离不开……」点明成功要素：技术协同突破加政策扶持与长期投入。B项是这一综合结论的准确转述。A项「已经成熟」言过其实；C项只是引子；D项只是技术层面的一个例证。故选C", "diff": 2},{"id": "yy-8025", "module": "yanyu", "prompt": "下列说法与文意相符的是：城市绿化中，「大树进城」曾一度流行。把农村的大树移栽到城市，短期内确实能快速成形，但大树移栽成活率低，运输和养护成本高昂，还会破坏乡村生态。业内专家建议，城市绿化应优先选用乡土树种、适地适树，把功夫下在「种」上而不是「买」上。", "options": ["大树移栽成活率低且成本高，还会破坏乡村生态", "城市绿化快速成形只能依靠大树移栽", "城市绿化必须完全禁止使用外来树种", "乡土树种的观赏价值高于外来树种"], "answer": 0, "explanation": "A项与文段「大树移栽成活率低，运输和养护成本高昂，还会破坏乡村生态」一一对应，是相符项。B项「完全禁止」过于绝对，文中只说「优先选用乡土树种」；C项「观赏价值」文中未比较；D项与文意相反，文中恰恰不提倡大树移栽。故选A", "diff": 2},{"id": "yy-8026", "module": "yanyu", "prompt": "下列说法与文意相符的是：睡眠是大脑的「清洁工」。研究发现，深度睡眠期间，大脑中的类淋巴系统会加速清除代谢废物，包括与阿尔茨海默病相关的β-淀粉样蛋白。长期睡眠不足，这些废物堆积，可能增加神经退行性疾病的风险。因此，保证充足且规律的睡眠，是保护大脑健康的重要一环。", "options": ["类淋巴系统只在夜间工作", "深度睡眠期间大脑清除代谢废物的效率更高", "睡眠时间越长大脑越健康", "β-淀粉样蛋白是导致失眠的主要原因"], "answer": 1, "explanation": "A项与文段「深度睡眠期间，大脑中的类淋巴系统会加速清除代谢废物」一致。B项「越长越健康」过度引申，文中强调的是「充足且规律」；C项因果倒置，文中说的是睡眠不足可能增加相关疾病风险；D项「只在夜间工作」文中未提及，属于无中生有。故选B", "diff": 2},{"id": "yy-8027", "module": "yanyu", "prompt": "这段文字主要说明：快递包装的绿色化，不能只靠快递企业的自觉。数据显示，我国快递年业务量超过千亿件，产生的包装废弃物数量惊人。虽然可降解包装、循环快递盒不断推广，但成本高、回收难仍是拦路虎。破解之道在于形成合力：政策端完善标准与补贴，企业端创新包装模式，消费者端养成绿色收寄习惯，缺一不可。", "options": ["绿色包装推广面临成本与回收难题", "快递包装绿色化需要政策、企业、消费者协同发力", "可降解包装是解决快递污染的唯一出路", "快递包装废弃物数量惊人"], "answer": 1, "explanation": "文段先指出快递包装问题的规模与绿色化的困境，末句「破解之道在于形成合力」引出重点：政策、企业、消费者三方协同。C项是对这一对策的完整概括。A、B两项分别是问题背景；D项「唯一出路」表述绝对且文中未提。故选B", "diff": 2},{"id": "yy-8028", "module": "yanyu", "prompt": "这段文字意在强调：古籍是中华文明的重要载体，但古籍保护面临「人才荒」：全国从事古籍修复的专业人员仅千余人，而待修复古籍数以千万计。修复人才成长周期长、待遇偏低，导致「招不来、留不住」。有学者呼吁，应通过完善学科建设、提高职业待遇、建立师承制度等方式，让更多年轻人愿意坐上修复台。", "options": ["我国待修复古籍数量庞大", "年轻人对古籍修复缺乏兴趣", "古籍修复技术门槛高、难度大", "古籍修复需要完善人才培养与激励机制"], "answer": 3, "explanation": "文段先摆出古籍修复人才短缺的现状及原因，末句以「应通过……」提出对策：完善学科建设、提高待遇、建立师承制度。A项「完善人才培养与激励机制」是对这些对策的整合概括。B、C、D三项分别对应文段的部分信息，但都不是文段意在强调的核心。故选D", "diff": 2},{"id": "yy-8029", "module": "yanyu", "prompt": "这段文字主要说明：社区食堂火了，但「办得快」更要「办得久」。一些社区食堂开业时红红火火，几个月后却因客源不足、成本高企而关门。要让社区食堂可持续运营，关键在于精准定位：既服务老年人，也向周边上班族、租户开放，用市场化收入反哺公益属性；政府则应在场地租金、水电费用上给予适度支持，而不是大包大揽。", "options": ["社区食堂应兼顾公益属性与市场化运营", "政府应全额承担社区食堂运营成本", "社区食堂只应服务老年群体", "社区食堂关门的原因是客源不足"], "answer": 0, "explanation": "文段由社区食堂「办得快」与「办得久」的矛盾切入，末句给出可持续之道：面向多元客群、市场化收入反哺公益、政府适度支持。B项「兼顾公益属性与市场化运营」是对这一思路的准确概括。A项只是现象；C项与「适度支持、不大包大揽」相悖；D项与「向上班族、租户开放」矛盾。故选A", "diff": 2},{"id": "yy-8030", "module": "yanyu", "prompt": "这段文字意在强调：数字经济时代，数据成为新型生产要素。然而，数据要素市场仍面临确权难、定价难、流通难等瓶颈。专家指出，数据确权是首要问题：谁拥有数据、谁能使用数据、数据收益如何分配，都需要制度层面的清晰界定。只有把产权规则立起来，数据要素才能放心地「跑」起来。", "options": ["数据要素市场存在三大瓶颈", "数据确权需要制度层面的清晰界定", "数据是数字经济时代的新型生产要素", "数据流通能够创造巨大价值"], "answer": 1, "explanation": "文段先介绍数据要素及其市场瓶颈，随后借专家之口指出「数据确权是首要问题」，末句「只有把产权规则立起来」进一步强调制度界定的必要性。C项正是文段意在强调的核心。A项是背景铺垫；B项是问题罗列；D项文中未展开。故选B", "diff": 2},{"id": "yy-8031", "module": "yanyu", "prompt": "①然而，随着城市化进程加快，许多老手艺面临后继无人的窘境。②传统手工艺是民族文化的重要载体，蕴含着世代匠人的智慧与审美。③为此，各地纷纷建立非遗工坊，让老手艺对接新市场。④一些技艺甚至只剩寥寥数位高龄传承人，抢救性保护刻不容缓。⑤好在政策扶持与市场培育正在形成合力，老手艺正焕发新生机。将以上句子重新排列，语序正确的是：", "options": ["①④②③⑤", "②①③④⑤", "②④①③⑤", "②①④③⑤"], "answer": 3, "explanation": "②提出话题「传统手工艺是重要载体」，①以「然而」转折指出后继无人的窘境，④用「甚至」递进说明技艺濒危，③以「为此」引出应对措施，⑤以「好在」收束展望。整体逻辑为：价值—困境—加剧—对策—成效。B项将④置于①前，递进关系错位；C项以转折开头，话题突兀；D项将对策③置于困境④之前，因果颠倒。故选D", "diff": 2},{"id": "yy-8032", "module": "yanyu", "prompt": "①数字经济的发展，为中小企业带来了前所未有的机遇。②不过，数字化转型并非一蹴而就，资金、人才、技术都是现实门槛。③中小企业是国民经济的毛细血管，其活力关乎就业与民生。④政府与平台企业应协同发力，降低转型成本，让中小企业敢转、会转。⑤因此，需要完善服务体系，提供低成本、轻量化的数字化工具。将以上句子重新排列，语序正确的是：", "options": ["③②①⑤④", "③①②⑤④", "①③②④⑤", "③①⑤②④"], "answer": 1, "explanation": "③引出话题「中小企业是毛细血管」，①说明数字经济带来的机遇，②以「不过」转折指出转型门槛，⑤以「因此」给出对策——完善服务体系提供工具，④进一步说明政府与平台协同发力。逻辑为：话题—机遇—困境—对策一—对策深化。B项②的转折缺少①的铺垫；C项以机遇开头、话题后置，结构松散；D项⑤的「因此」紧接机遇，因果不通。故选B", "diff": 2},{"id": "yy-8033", "module": "yanyu", "prompt": "①垃圾分类看似小事，实则关乎生态文明建设全局。②习惯的养成非一日之功，需要持续引导与制度约束并重。③近年来，多个城市推行垃圾分类，居民参与率显著提升。④但也要看到，部分居民仍存在「前端分类、后端混装」的疑虑，影响了参与积极性。⑤对此，应加强收运环节的透明化，让居民看到分类的真实成效。将以上句子重新排列，语序正确的是：", "options": ["①③④②⑤", "①④③②⑤", "③①④⑤②", "①③②④⑤"], "answer": 0, "explanation": "①总起点明垃圾分类的意义，③介绍推行成效，④以「但也要看到」指出居民疑虑，②分析习惯养成需要引导与约束，⑤以「对此」给出针对性措施。逻辑为：意义—成效—问题—分析—对策。B项②的「习惯养成」分析插在问题④之前，衔接生硬；C项以成效开头、意义后置，首句不当；D项④紧随①后缺少成效铺垫，转折突兀。故选A", "diff": 2},{"id": "yy-8034", "module": "yanyu", "prompt": "①「银发经济」正成为新的增长点。②如何让老年人敢消费、愿消费，需要产品设计与市场规范双管齐下。③我国60岁以上人口已超过2.9亿，老年消费市场潜力巨大。④然而，市场上针对老年人的产品和服务供给仍显不足，虚假宣传、质量参差等问题也时有发生。⑤从康养旅居到适老化改造，从老年教育到智慧助老，需求持续释放。将以上句子重新排列，语序正确的是：", "options": ["①⑤③④②", "③①⑤④②", "①③⑤④②", "③④①⑤②"], "answer": 2, "explanation": "①提出「银发经济成为增长点」的话题，③用人口数据支撑市场潜力，⑤列举需求释放的具体领域，④以「然而」指出供给不足与乱象，②给出双管齐下的对策。逻辑为：话题—数据支撑—需求表现—问题—对策。B项以数据开头、话题后置，首句不当；C项⑤的列举紧接话题后缺少数据支撑，衔接松散；D项④的转折缺少需求铺垫，逻辑断裂。故选C", "diff": 2},{"id": "yy-8035", "module": "yanyu", "prompt": "①湿地被称为「地球之肾」，具有涵养水源、净化水质、调节气候等多重功能。②近年来，我国湿地保护体系不断完善，一批湿地公园相继建成开放。③不过，湿地保护仍面临侵占、污染等威胁，保护与发展的平衡仍需持续探索。④候鸟归来、芦苇摇曳，湿地公园成为市民亲近自然的好去处。⑤这背后，是退耕还湿、生态补偿等一系列制度安排的支撑。将以上句子重新排列，语序正确的是：", "options": ["①②④⑤③", "①④②⑤③", "②①④⑤③", "①②⑤④③"], "answer": 0, "explanation": "①总起介绍湿地的功能与价值，②说明保护体系完善、湿地公园建成，④描绘公园成为市民好去处的景象，⑤以「这背后」揭示④背后的制度支撑，③以「不过」转折指出仍面临的威胁。逻辑为：价值—建设成效—景象—制度支撑—问题展望。A项⑤的「这背后」指代对象不明；B项④的景象紧接功能介绍，缺少建设成效的铺垫；C项以②开头，话题突兀。故选A", "diff": 2},{"id": "yy-8036", "module": "yanyu", "prompt": "填入画横线部分最恰当的一项是：数字经济浪潮下，直播带货成为农产品出村进城的新通道。______________。对此，相关部门应加强主播资质审核与内容监管，让直播助农行稳致远。", "options": ["许多农民通过直播实现了增收致富", "然而，个别主播夸大宣传、以次充好，透支了消费者信任", "直播带货的销售额逐年攀升，成绩喜人", "农产品电商的发展离不开物流体系的完善"], "answer": 1, "explanation": "横线位于段中，后文「对此，相关部门应加强……监管」表明横线处应提出需要监管的问题。A项「夸大宣传、以次充好，透支信任」正是需要监管的问题，与后文衔接紧密。B、D两项是正面成绩，无法引出监管对策；C项物流话题与后文监管无关。故选B", "diff": 2},{"id": "yy-8037", "module": "yanyu", "prompt": "填入画横线部分最恰当的一项是：城市治理的最终目的是让人民宜居宜业。______________。从「12345」热线到「随手拍」小程序，市民参与城市治理的渠道越来越畅通，共建共治共享的格局正在形成。", "options": ["近年来，各地纷纷搭建民意直通平台，让市民成为治理的参与者", "一些城市存在治理粗放、回应迟缓的问题", "城市基础设施投入逐年增加，市容市貌显著改善", "智慧城市建设需要大量资金和技术投入"], "answer": 0, "explanation": "横线后「从『12345』热线到『随手拍』小程序，市民参与渠道越来越畅通」是对横线处的具体例证，横线处应提出「搭建平台让市民参与治理」这一总括句。A项与之衔接自然。B项讲基础设施，与「参与渠道」无关；C项讲问题，与后文正面例证矛盾；D项讲资金技术，话题偏离。故选A", "diff": 2},{"id": "yy-8038", "module": "yanyu", "prompt": "填入画横线部分最恰当的一项是：文化遗产数字化让古老文明以新形态存续。通过三维扫描、全景影像等技术，敦煌壁画、故宫建筑得以永久保存并在线展示。______________。数字化的意义不仅在于保存，更在于让更多人便捷地触摸文明。", "options": ["数字化技术仍在不断迭代升级", "文物数字化需要投入大量资金与专业人才", "观众足不出户就能「云游」博物馆，文化资源的可及性大幅提升", "实体博物馆的参观体验仍不可替代"], "answer": 2, "explanation": "横线前讲技术让文物得以保存并在线展示，横线后总结「数字化的意义在于让更多人便捷地触摸文明」，横线处应承接「在线展示」讲公众便捷访问的效果。A项「足不出户云游、可及性提升」承上启下。B、C、D三项均无法同时衔接前后文。故选C", "diff": 2},{"id": "yy-8039", "module": "yanyu", "prompt": "填入画横线部分最恰当的一项是：基层减负不能「一刀切」地减。______________。比如，必要的台账是规范工作的抓手，关键在于剔除形式主义的「痕」，保留服务群众的「迹」。", "options": ["群众对基层工作的满意度逐年提升", "基层干部的负担主要来自各类考核检查", "数字化办公工具能够有效减轻基层负担", "减负减的是形式主义的负担，而不是工作责任"], "answer": 3, "explanation": "横线后「比如，必要的台账是规范工作的抓手，关键在于剔除形式主义的『痕』」是对横线观点的例证，横线处应提出「减负减的是形式主义而非责任」这一观点。A项与之完全对应。B项讲负担来源，与「不能一刀切」的辩证讨论无关；C、D两项话题偏离。故选D", "diff": 2},{"id": "yy-8040", "module": "yanyu", "prompt": "填入画横线部分最恰当的一项是：夜间经济是城市活力的晴雨表。______________。从延长博物馆开放时间到开设深夜食堂，从夜游景区到灯光秀场，多元业态让城市的夜晚亮起来、人气聚起来。", "options": ["丰富夜间消费供给，是激发夜间经济潜力的关键", "不少城市的夜间经济仍停留在餐饮层面", "夜间经济也带来了噪音扰民、光污染等问题", "发展夜间经济需要完善公共交通配套"], "answer": 0, "explanation": "横线后「从延长开放时间到深夜食堂，从夜游到灯光秀」是多元消费业态的列举，横线处应提出「丰富夜间消费供给」这一总起句。A项与之衔接自然。B项讲问题，与后文正面列举矛盾；C项「停留在餐饮层面」与「多元业态」矛盾；D项交通配套话题偏离。故选A", "diff": 2},{"id": "yy-8041", "module": "yanyu", "prompt": "文段接下来最可能讨论的是：近年来，人工智能在医疗影像诊断领域表现亮眼，部分任务上的准确率已超过初级医生。然而，AI诊断的落地仍面临多重障碍：数据孤岛导致训练样本受限，算法「黑箱」让医生难以信任，责任界定更是悬而未决——AI误诊，责任在医生、医院还是算法开发者？", "options": ["医疗数据共享平台的建设进展", "医生如何与AI工具协同工作", "AI医疗影像诊断的准确率提升路径", "AI诊断责任界定的制度设计探讨"], "answer": 3, "explanation": "文段末句以「责任界定更是悬而未决」收尾，并用连续设问聚焦「AI误诊责任在谁」，按话题一致原则，下文最可能围绕责任界定如何落地展开。D项正确。A项「数据共享」是前文障碍之一，已被带过；B项「协同工作」与末句焦点偏离；C项准确率是前文已述内容。故选D", "diff": 2},{"id": "yy-8042", "module": "yanyu", "prompt": "文段接下来最可能讨论的是：社区养老驿站如雨后春笋般涌现，为老年人提供助餐、助浴、康复理疗等服务。不过，不少驿站运营陷入「叫好不叫座」的尴尬：服务价格高了老人不愿来，低了驿站难以为继。收支平衡的难题，成为社区养老可持续发展的「拦路虎」。", "options": ["政府补贴在养老服务中的作用", "社区养老驿站的服务项目有哪些", "老年人对养老服务的真实需求", "养老驿站破解收支难题的运营探索"], "answer": 3, "explanation": "文段末句点明「收支平衡的难题」是可持续发展的「拦路虎」，话题落在运营困境上，下文最可能围绕如何破解收支难题展开。D项正确。A项是背景介绍；B项服务项目列举与收支话题衔接不紧；C项「政府补贴」只是可能的解法之一，且文段未提及补贴。故选D", "diff": 2},{"id": "yy-8043", "module": "yanyu", "prompt": "文段接下来最可能讨论的是：预制菜产业近年高速增长，但消费者疑虑也随之而来：菜品新鲜度如何保证？添加剂是否超标？营养会不会流失？这些疑问背后，是行业标准缺失带来的信任赤字。目前，预制菜的国标仍在制定中，企业各自为战，质量良莠不齐。", "options": ["预制菜行业的市场规模与增长预测", "消费者对预制菜的接受度调查", "冷链物流对预制菜品质的影响", "预制菜国家标准制定的重点与进展"], "answer": 3, "explanation": "文段末句指出「预制菜的国标仍在制定中，企业各自为战」，话题聚焦标准缺失，下文最可能围绕国标制定的重点与进展展开。D项正确。A项市场规模是背景；B项接受度与末句话题偏离；C项冷链是品质影响因素之一，非末句焦点。故选D", "diff": 2},{"id": "yy-8044", "module": "yanyu", "prompt": "文段接下来最可能讨论的是：城市「口袋公园」建设如火如荼，边角地、闲置地变身居民家门口的绿色空间。不过，建起来只是第一步，管好、用好才是长久之计。一些口袋公园建成后缺乏养护，设施损坏无人修，绿地渐成荒地，居民从欣喜到惋惜。", "options": ["口袋公园长效管护机制的建立", "口袋公园的选址原则与设计理念", "口袋公园对周边房价的影响", "国外口袋公园建设的成功经验"], "answer": 0, "explanation": "文段末句聚焦「建成后缺乏养护」的问题，话题落在「管好用好」上，下文最可能围绕长效管护机制展开。A项正确。B项选址设计是「建起来」阶段的内容；C项房价与文段话题无关；D项国外经验可能涉及管护，但不如A项直接承接末句问题。故选A", "diff": 2},{"id": "yy-8045", "module": "yanyu", "prompt": "文段接下来最可能讨论的是：无人机送快递正在从试验走向常态，多条城市低空物流航线陆续开通。低空经济的大门正在打开，但空域管理、飞行安全、隐私保护等课题也随之而来。如何为无人机划出安全、高效的「空中走廊」，考验着城市治理的精细化水平。", "options": ["低空经济的产业规模与增长空间", "低空空域管理制度的改革探索", "无人机技术的迭代升级方向", "无人机快递的成本结构分析"], "answer": 1, "explanation": "文段末句聚焦「如何为无人机划出安全高效的空中走廊」，即空域管理问题，下文最可能围绕空域管理制度的改革展开。B项正确。A项产业规模是背景；C项技术升级与「治理精细化」的落点不符；D项成本与末句话题偏离。故选B", "diff": 2},{"id": "yy-8046", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：基层工作千头万绪，年轻干部要沉下心来，______群众急难愁盼，一件一件抓落实，才能赢得群众信任。", "options": ["聚焦", "环顾", "凝视", "注视"], "answer": 0, "explanation": "「聚焦」比喻把注意力集中到重点上，与「急难愁盼」搭配规范，是政务语境惯用语。「凝视」「注视」都指目光注视具体对象，用于抽象问题不妥；「环顾」指向四周看，与「抓落实」的专注语义矛盾。故选A", "diff": 2},{"id": "yy-8047", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：推动科技成果转化，要______实验室与生产线之间的鸿沟，让创新价值充分涌流。", "options": ["弥合", "跨越", "抹平", "填补"], "answer": 0, "explanation": "「弥合」指使双方关系或裂缝愈合，与「鸿沟」是规范搭配，强调消除隔阂的过程性。「填补」多与「空白、漏洞」搭配；「跨越」强调跳过，与「鸿沟」搭配后语义侧重「越过」而非「消除」；「抹平」口语化且多用于账目、差距，语体不合。故选A", "diff": 2},{"id": "yy-8048", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：老城区改造要______历史文脉，避免「千城一面」，让每条街巷都有自己的故事。", "options": ["继承", "保留", "延续", "沿袭"], "answer": 2, "explanation": "「延续」指照原样持续下去，与「文脉」搭配自然，强调文脉的动态传承。「继承」多与「遗产、事业」搭配，主体多为人；「沿袭」多与「制度、旧例」搭配，含因循守旧色彩；「保留」指保持不变，缺少「传承发展」的动态感。故选C", "diff": 2},{"id": "yy-8049", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：面对汛期考验，各地要______，提前排查风险隐患，确保安全度汛。", "options": ["亡羊补牢", "坐以待毙", "临阵磨枪", "未雨绸缪"], "answer": 3, "explanation": "「未雨绸缪」指趁天没下雨先修缮房屋，比喻提前做好准备，与「提前排查隐患」完全对应。「亡羊补牢」指事后补救，与「提前」矛盾；「临阵磨枪」指事到临头才匆忙准备，含贬义；「坐以待毙」指消极等待，语义过重且态度错误。故选D", "diff": 2},{"id": "yy-8050", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：优化营商环境，既要______审批流程，提高办事效率，也要加强事中事后监管，守住安全底线。", "options": ["精简", "精炼", "削减", "简化"], "answer": 0, "explanation": "「精简」指去掉不必要的部分使紧凑，与「流程」搭配规范，且含「去繁就简、保留必要」之意，与后文「加强监管」的辩证关系呼应。「精炼」多与语言、文字搭配；「简化」语义相近但缺少「精当」之意；「削减」多与「经费、数量」搭配，含削减过度之嫌。故选A", "diff": 2},{"id": "yy-8051", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：文艺创作要______时代脉搏，______人民心声，才能创作出有筋骨、有温度的作品。", "options": ["抓住 聆听", "掌握 观看", "把握 倾听", "感受 注视"], "answer": 2, "explanation": "「把握脉搏」「倾听心声」均为规范搭配：「把握」强调对抽象事物的掌控，与「脉搏」的动态特征契合；「倾听」含认真听取之意，与「心声」搭配自然。B项「掌握脉搏」搭配不当，「观看心声」动宾错配；C项「抓住脉搏」尚可但「聆听心声」偏书面庄重，整体不如A项；D项「感受脉搏」「注视心声」搭配均不当。故选C", "diff": 2},{"id": "yy-8052", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：乡村医生是农村居民健康的「守门人」，要______他们的待遇，______他们的职业发展通道，让人才下得去、留得住。", "options": ["增强 拓展", "提高 拓宽", "提升 延伸", "改善 开辟"], "answer": 1, "explanation": "「提高待遇」「拓宽通道」均为规范搭配：「提高」与「待遇」搭配自然；「拓宽」与「通道」搭配强调路径的延展性。B项「延伸通道」搭配生硬；C项「改善待遇」尚可但「开辟通道」与「职业发展」的搭配不如「拓宽」精准；D项「增强待遇」搭配不当。故选B", "diff": 2},{"id": "yy-8053", "module": "yanyu", "prompt": "把下列句子组成语意连贯的一段话，排序最恰当的一项是：①但数字经济也带来垄断、隐私泄露等新问题②数字经济已成为经济增长的重要引擎③需要完善法律法规，加强协同监管④近年来，数字技术深度融入生产生活⑤对此，各国纷纷探索治理之道", "options": ["②①④③⑤", "④①②⑤③", "②④①⑤③", "④②①⑤③"], "answer": 3, "explanation": "④以时间背景「近年来」引出数字技术融入生产生活，②顺势指出数字经济成为增长引擎，①以「但」转折指出新问题，⑤以「对此」引出各国探索治理，③说明治理的具体方向——完善法规、协同监管。逻辑为：背景—地位—问题—回应—具体措施。B项②作首句缺少④的时间铺垫；C项①的转折缺少②的正面陈述；D项③的「需要」缺少⑤的「对此」承接。故选D", "diff": 2},{"id": "yy-8054", "module": "yanyu", "prompt": "把下列句子组成语意连贯的一段话，排序最恰当的一项是：①读书的意义，不仅在于获取知识，更在于滋养精神②腹有诗书气自华，一个人的精神底色，往往由阅读塑造③从这个意义上说，阅读是最值得坚持的人生投资④碎片化时代，很多人抱怨没有时间读书⑤其实，每天挤出半小时，一年就能读完十几本书", "options": ["①④⑤②③", "①②④⑤③", "④①②⑤③", "④⑤①②③"], "answer": 3, "explanation": "④以「碎片化时代」的现实困境引入，⑤以「其实」给出解法并举例，①顺势升华读书的意义，②用「腹有诗书气自华」印证精神滋养，③以「从这个意义上说」总结收束。逻辑为：困境—解法—意义—印证—总结。B项①作首句缺少现实语境引入；C项①置于④后衔接生硬，且②⑤顺序颠倒；D项④紧随①后转折突兀。故选D", "diff": 2},{"id": "yy-8055", "module": "yanyu", "prompt": "把下列句子组成语意连贯的一段话，排序最恰当的一项是：①绿色低碳发展不是要限制发展，而是要实现更高质量的发展②产业转型升级是必由之路③传统产业通过技术改造可以焕发新的生机④新兴产业则代表未来方向，需要前瞻布局⑤两者并举，才能构建绿色现代化的产业体系", "options": ["①②④③⑤", "①③②④⑤", "②①③④⑤", "①②③④⑤"], "answer": 3, "explanation": "①提出「绿色低碳发展是更高质量的发展」的总观点，②指出产业转型升级是必由之路，③说明传统产业改造的路径，④以「则」对举新兴产业的布局，⑤以「两者并举」总结收束。逻辑为：总起—路径—传统产业—新兴产业—总结。B项②作首句缺少总观点；C项③的「传统产业」缺少②的引出；D项④的「则」缺少③的对举对象。故选D", "diff": 2},{"id": "yy-8056", "module": "yanyu", "prompt": "把下列句子组成语意连贯的一段话，排序最恰当的一项是：①社区是城市治理的「最后一公里」②网格员、志愿者、物业人员协同联动，把服务送到居民身边③近年来，各地推行「党建+社区治理」模式④居民有事「就近说、马上办」，获得感显著增强⑤党组织牵头整合各方资源，织密服务网络", "options": ["①⑤③②④", "①③⑤②④", "③⑤①②④", "③①⑤②④"], "answer": 1, "explanation": "①提出「社区是最后一公里」的话题，③介绍各地推行的治理模式，⑤说明党组织整合资源的做法，②说明各方协同把服务送到身边，④以「获得感显著增强」收束成效。逻辑为：话题—模式—做法—服务—成效。B项③作首句缺少①的话题引入；C项⑤的「整合资源」缺少③的模式铺垫；D项⑤紧随③后缺少①的话题，且①的位置突兀。故选B", "diff": 2},{"id": "yy-8057", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：文化遗产保护要______，既不能过度开发，也不能一味封存，要在保护中发展、在发展中保护。", "options": ["量力而行", "权衡利弊", "顾此失彼", "统筹兼顾"], "answer": 3, "explanation": "「统筹兼顾」指统一筹划、全面照顾，与后文「既不能……也不能……」的辩证要求一致。「顾此失彼」指不能全面照顾，与文意相悖；「权衡利弊」指比较得失后作决定，强调「选择」而非「兼顾」；「量力而行」指按自身力量行事，与「保护与发展并重」的语境不符。故选D", "diff": 2},{"id": "yy-8058", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：政务公开不能______，公开什么、怎么公开，要以群众需求为导向，让群众看得懂、用得上。", "options": ["各自为政", "自说自话", "自以为是", "自娱自乐"], "answer": 1, "explanation": "「自说自话」指不顾他人反应、自顾自表达，与后文「以群众需求为导向」形成对照，批评公开内容脱离群众需求。「自娱自乐」指自己找乐子，语体偏生活化；「各自为政」指各自行动不配合，强调「内部不协同」而非「脱离群众」；「自以为是」指自认正确，与语境不符。故选B", "diff": 2},{"id": "yy-8059", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：人工智能技术日新月异，但技术进步不能______伦理底线，算法应用必须接受价值审视。", "options": ["穿越", "逾越", "超越", "跨越"], "answer": 1, "explanation": "「逾越」指越过、超越界限，多与「底线、红线、雷池」搭配，含「不可触碰」的规范意味。「跨越」多与「障碍、门槛」搭配，是中性词；「穿越」多用于时空、具体空间；「超越」多与「自我、对手」搭配，是中性偏褒义词，均不如「逾越」契合「底线不可触碰」的语境。故选B", "diff": 2},{"id": "yy-8060", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：老旧小区改造，居民意见最重要。改造方案要______民意，改哪里、怎么改，让居民说了算。", "options": ["参考", "服从", "尊重", "尊重并吸纳"], "answer": 2, "explanation": "语境强调「让居民说了算」，方案制定应「尊重民意」，A项简洁准确，与后文「说了算」呼应。「尊重并吸纳」中「吸纳」与「民意」搭配后语义过重，且与「说了算」重复；「参考」程度不足，与「说了算」矛盾；「服从」主体错位，方案不能「服从」民意，应是「依据」。故选C", "diff": 2},{"id": "yy-8061", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：青年科研人员要敢于______「无人区」，勇闯科学前沿，不能总跟在别人后面做跟随研究。", "options": ["闯入", "深入", "步入", "踏入"], "answer": 0, "explanation": "「闯入」含主动突破、勇于开拓之意，与「无人区」「勇闯」的开拓语境一致。「踏入」「步入」都是中性进入，缺少「敢为人先」的锐气；「深入」多与「研究、调查」搭配，与「无人区」的比喻义搭配不当。故选A", "diff": 2},{"id": "yy-8062", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：乡村振兴不能只靠政府「独角戏」，要______社会力量参与，形成多元投入格局。", "options": ["指导", "引导", "倡导", "领导"], "answer": 1, "explanation": "「引导」指带领、指引方向，强调通过政策、机制把社会力量引向参与，与「形成多元投入格局」的机制性语境契合。「领导」指率领并朝一定方向前进，多用于上下级关系，与「社会力量」的关系不符；「指导」侧重业务指点；「倡导」只提「提倡」而缺少「机制牵引」之意。故选B", "diff": 2},{"id": "yy-8063", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：政务新媒体要办出实效，不能只图形式热闹，关键要______群众关切，提升服务效能。", "options": ["回答", "反馈", "回应", "答复"], "answer": 2, "explanation": "「回应关切」是规范搭配，「回应」含对问题的应答与处理，与「提升服务效能」衔接自然。「回答」「答复」都只强调「给出答案」，缺少「处理问题」的行动意味；「反馈」指信息返回，主体与语境不符。故选C", "diff": 2},{"id": "yy-8064", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：历史文化遗产不仅属于我们这一代，更属于子孙后代，保护工作要______，不能急功近利。", "options": ["着眼当前", "立足现实", "着眼长远", "脚踏实地"], "answer": 2, "explanation": "「着眼长远」与后文「属于子孙后代」「不能急功近利」形成呼应，强调保护工作的长期性。「着眼当前」「立足现实」都与「急功近利」的批评方向一致，与文意相悖；「脚踏实地」强调踏实做事，与「长期性」的语境不符。故选C", "diff": 2},{"id": "yy-8065", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：深化「放管服」改革，要______市场准入负面清单之外的事项，市场主体「法无禁止即可为」。", "options": ["放活", "放宽", "放弃", "放开"], "answer": 3, "explanation": "「放开」指解除限制、允许进入，与「负面清单之外」「法无禁止即可为」的市场准入语境契合。「放宽」多与「条件、限制」搭配，强调「放松标准」；「放活」多用于「放活经营」，强调经营方式；「放弃」指抛弃，语义完全不合。故选D", "diff": 2},{"id": "yy-8066", "module": "yanyu", "prompt": "这段文字主要说明：随着老龄化程度加深，「老漂族」群体日益庞大——为照顾孙辈而随迁的老年人，在陌生城市面临语言不通、社交圈窄、异地医保报销不便等困境。他们为家庭默默付出，却常常被城市公共服务体系忽视。让「老漂族」融入城市，需要在医保异地结算、社区融入、精神关爱等方面拿出更细致的安排。", "options": ["「老漂族」为照顾孙辈随迁进城", "「老漂族」面临融入困境，公共服务应更细致地关照他们", "城市老龄化程度不断加深", "异地医保结算是「老漂族」最迫切的需求"], "answer": 1, "explanation": "文段先介绍「老漂族」群体的出现及其困境，末句以「需要在……拿出更细致的安排」提出对策，主旨是「老漂族的融入困境与公共服务应更细致关照」。B项完整概括。A项只是背景；C项「最迫切」文中未比较；D项偏离主题。故选B", "diff": 2},{"id": "yy-8067", "module": "yanyu", "prompt": "这段文字意在强调：近年来，「剧本杀」等沉浸式娱乐业态快速扩张，成为年轻人的社交新宠。但行业快速膨胀的同时，也出现了内容良莠不齐、消防安全隐患、未成年人保护缺位等问题。规范不是限制发展，而是为行业划定底线，让从业者有章可循，让消费者玩得安心。", "options": ["未成年人保护是行业监管的重点", "「剧本杀」成为年轻人社交新宠", "行业规范是为了让行业更好地发展", "沉浸式娱乐行业存在多重问题"], "answer": 2, "explanation": "文段先介绍沉浸式娱乐的兴起，再指出其存在的问题，末句以「规范不是限制发展，而是……」点明意图：规范的目的是促进行业更好发展。C项准确转述。A项是背景；B项是问题描述；D项只是问题之一。故选C", "diff": 2},{"id": "yy-8068", "module": "yanyu", "prompt": "这段文字主要说明：气象数据显示，近十年我国极端天气事件呈多发、频发态势。城市在快速扩张中，「摊大饼」式的开发挤占了河湖水系与绿地，削弱了城市「海绵」功能。建设韧性城市，要把生态空间还给城市，让雨水有处可去，让城市有弹性地应对气候风险。", "options": ["我国极端天气事件呈多发、频发态势", "气候变化对城市的影响日益显著", "建设韧性城市需要恢复城市生态空间、增强应对能力", "城市无序开发削弱了生态调节功能"], "answer": 2, "explanation": "文段先指出极端天气频发的背景，再分析城市开发挤占生态空间、削弱「海绵」功能的问题，末句提出建设韧性城市的路径：把生态空间还给城市、增强弹性应对。C项完整概括主旨。A、D两项是背景；B项是问题分析。故选C", "diff": 2},{"id": "yy-8069", "module": "yanyu", "prompt": "这段文字意在强调：非遗传承，「人」是核心。传承人是非遗的活态载体，传承人老去、后继乏人，非遗就可能「人亡艺绝」。因此，非遗保护不能只见「遗」不见「人」，要把传承人的培养、扶持摆在突出位置，让传承人有尊严、有奔头，非遗才能代代相传。", "options": ["传承人是非遗活态传承的核心，应重点培养扶持", "非遗面临「人亡艺绝」的风险", "非遗是中华优秀传统文化的重要组成部分", "非遗保护需要政府和社会共同参与"], "answer": 0, "explanation": "文段围绕「人是非遗传承的核心」展开，末句以「因此」提出对策：把传承人的培养、扶持摆在突出位置。B项准确概括意图。A项是常识性背景；C项是风险描述；D项「政府和社会共同参与」文中未展开。故选A", "diff": 2},{"id": "yy-8070", "module": "yanyu", "prompt": "下列说法与文意相符的是：盐雾试验是一种加速腐蚀试验，通过模拟海洋大气环境，评估材料与产品的耐腐蚀性能。试验中，试样置于密闭试验箱内，接受一定浓度的氯化钠溶液喷雾，在规定温度与时间后观察其腐蚀程度。需要注意的是，盐雾试验结果与真实海洋环境的腐蚀情况并非线性对应，只能作为相对比较的参考。", "options": ["盐雾试验箱内温度越低，腐蚀速度越快", "盐雾试验结果能精确预测材料在海洋环境中的使用寿命", "所有材料都需要进行盐雾试验", "盐雾试验通过模拟海洋大气环境评估材料耐腐蚀性能"], "answer": 3, "explanation": "A项与文段首句「通过模拟海洋大气环境，评估材料与产品的耐腐蚀性能」一致。B项与「并非线性对应，只能作为相对比较的参考」相悖；C项「温度越低腐蚀越快」文中未提及且违背常识；D项「所有材料」表述绝对。故选D", "diff": 2},{"id": "yy-8071", "module": "yanyu", "prompt": "下列说法与文意相符的是：所谓「数字游民」，是指依托互联网技术、不受固定办公地点约束、可自由选择工作地点的从业者。他们或旅居海岛，或隐居山村，在旅行与工作之间寻找平衡。数字游民的出现，得益于远程协作工具的成熟与企业管理理念的转变。不过，这一群体也面临收入不稳定、社会保障缺失、职业发展受限等现实挑战。", "options": ["数字游民是指依托互联网技术、不受固定办公地点约束的从业者", "企业管理理念的转变阻碍了数字游民的出现", "数字游民的生活方式没有后顾之忧", "数字游民的收入普遍高于传统上班族"], "answer": 0, "explanation": "A项与文段对「数字游民」的定义一致。B项与「面临收入不稳定、社会保障缺失等现实挑战」相悖；C项与「得益于……企业管理理念的转变」相反；D项「收入普遍高于」文中未提及。故选A", "diff": 2},{"id": "yy-8072", "module": "yanyu", "prompt": "下列说法与文意相符的是：碳足迹是指某一产品或活动在整个生命周期中直接与间接产生的温室气体排放总量。从原料开采、生产制造，到运输销售、使用回收，每个环节都会留下「碳的脚印」。越来越多的企业开始披露产品碳足迹，消费者也可以通过碳标签了解产品的排放信息，用购买行为支持低碳产品。", "options": ["碳标签是企业自愿披露、没有任何约束力的形式", "碳足迹涵盖产品全生命周期的温室气体排放总量", "碳足迹只计算产品生产环节的直接排放", "消费者无法了解产品的碳排放信息"], "answer": 1, "explanation": "A项与文段「在整个生命周期中直接与间接产生的温室气体排放总量」一致。B项与「从原料到回收，每个环节」的表述相悖；C项与「消费者可以通过碳标签了解」矛盾；D项「没有任何约束力」文中未提及，且与「越来越多的企业开始披露」的语境不符。故选B", "diff": 2},{"id": "yy-8073", "module": "yanyu", "prompt": "下列说法与文意相符的是：城市内涝治理不能只靠「排」，更要学会「渗」与「蓄」。透水铺装、下沉式绿地、雨水花园等「海绵体」，能让雨水就地消纳、缓释慢排。相比传统的「以排为主」，海绵城市的理念是从「快排」转向「渗滞蓄净用排」并举，从源头削减径流，缓解管网压力。", "options": ["城市内涝治理只需要完善排水管网", "海绵城市理念强调「渗滞蓄净用排」并举，从源头削减径流", "下沉式绿地的主要功能是美化景观", "透水铺装会加剧城市内涝"], "answer": 1, "explanation": "A项与文段「从『快排』转向『渗滞蓄净用排』并举，从源头削减径流」一致。B项与「不能只靠排」相悖；C项与透水铺装「让雨水就地消纳」的功能相反；D项「美化景观」文中未提及，其主要功能是雨水消纳。故选B", "diff": 2},{"id": "yy-8074", "module": "yanyu", "prompt": "下列说法与文意相符的是：睡眠呼吸暂停综合征以夜间打鼾、呼吸暂停、白天嗜睡为主要表现。长期不干预，可增加高血压、冠心病、脑卒中等疾病风险。该病肥胖者多发，但并非肥胖者专属，颌面部结构异常、鼻中隔偏曲等解剖因素同样可能致病。中重度患者需要呼吸机治疗，轻度患者可通过减重、侧卧睡姿、戒酒等方式改善。", "options": ["打鼾是睡眠呼吸暂停综合征的特异性表现", "肥胖是睡眠呼吸暂停综合征的唯一致病因素", "睡眠呼吸暂停综合征患者均需呼吸机治疗", "睡眠呼吸暂停综合征可增加心脑血管疾病风险"], "answer": 3, "explanation": "C项与文段「可增加高血压、冠心病、脑卒中等疾病风险」一致。A项与「中重度患者需要呼吸机治疗」相悖，轻度患者可先行生活方式干预；B项与「并非肥胖者专属」矛盾；D项「特异性表现」不成立，打鼾在普通人群中也常见。故选D", "diff": 2},{"id": "yy-8075", "module": "yanyu", "prompt": "这段文字主要说明：随着「双碳」目标推进，绿色金融快速发展。绿色信贷、绿色债券规模持续扩大，但「洗绿」「漂绿」现象也时有发生——一些项目披上「绿色」外衣套取优惠资金，实际环境效益存疑。防范「洗绿」，需要统一绿色项目认定标准，强化信息披露与第三方评估，让「绿色」名副其实。", "options": ["企业套取优惠资金的行为应受处罚", "绿色信贷是绿色金融的主要形式", "绿色金融规模持续扩大", "「洗绿」现象损害绿色金融的健康发展，需要统一标准、强化披露来防范"], "answer": 3, "explanation": "文段先介绍绿色金融的发展，再指出「洗绿」问题，末句提出防范之道：统一认定标准、强化披露与评估。B项完整概括了问题与对策。A项是背景；C项「主要形式」文中未比较；D项只是对策的一个侧面且「应受处罚」文中未提。故选D", "diff": 2},{"id": "yy-8076", "module": "yanyu", "prompt": "这段文字意在强调：考古不是挖宝。考古学通过科学发掘与系统研究，重建古代社会的面貌，回答「我们从哪里来」的问题。文物出土只是第一步，后续的整理、检测、解读，往往需要数十年之功。公众对考古的关注是好事，但把考古等同于「挖宝」，既低估了这门学科的严谨，也容易助长文物贩卖的歪风。", "options": ["文物出土后需要数十年的整理研究", "公众对考古的关注度不断提高", "文物贩卖是违法行为", "考古学通过科学发掘与研究重建古代社会面貌，公众不应把考古等同于「挖宝」"], "answer": 3, "explanation": "文段开篇提出「考古不是挖宝」的观点，中间阐述考古学的科学内涵，末句回到「把考古等同于挖宝」的危害。A项完整概括了「考古的科学性」与「不应等同挖宝」两层意思。B、C、D三项都是文段的部分信息，非意图所在。故选D", "diff": 2},{"id": "yy-8077", "module": "yanyu", "prompt": "这段文字主要说明：近年来，「国潮」设计风靡市场，从服饰美妆到家电数码，传统元素与现代设计的融合让产品焕发新魅力。不过，「国潮」不是简单贴上传统纹样标签。真正打动消费者的，是设计对文化内涵的深入理解与创造性转化。若只做表面文章，消费者很快会审美疲劳，「国潮」也会沦为昙花一现的营销噱头。", "options": ["「国潮」的核心是文化内涵的创造性转化，而非表面元素的堆砌", "消费者对「国潮」产品很快会审美疲劳", "传统纹样是「国潮」设计的重要元素", "「国潮」设计风靡市场，产品焕发新魅力"], "answer": 0, "explanation": "文段先描述「国潮」的流行，转折后指出「不是简单贴标签」，进而点明核心是「对文化内涵的深入理解与创造性转化」。B项准确概括。A项是背景；C项是反面假设；D项与文意倾向相悖。故选A", "diff": 2},{"id": "yy-8078", "module": "yanyu", "prompt": "这段文字意在强调：社区治理中，「居民议事会」让居民自己讨论、自己决定身边事。从加装电梯到停车位改造，从垃圾分类点到健身器材更新，议事会讨论的事项件件与居民利益相关。实践证明，居民参与度越高，决策落地越顺畅，社区凝聚力也越强。基层治理现代化，需要把「参与权」真正交还给居民。", "options": ["社区凝聚力随着居民参与度提高而增强", "居民参与是社区治理有效运转的关键，应保障居民参与权", "居民议事会讨论的事项与居民利益相关", "基层治理现代化面临诸多挑战"], "answer": 1, "explanation": "文段先介绍居民议事会的实践，再以「实践证明」指出居民参与带来的三重效果，末句以「需要把参与权交还给居民」点明意图。B项准确概括。A、C两项是文段的部分信息；D项文中未展开。故选B", "diff": 2},{"id": "yy-8079", "module": "yanyu", "prompt": "这段文字主要说明：候鸟迁徙是自然界最壮观的旅程之一。每年春秋两季，数以亿计的候鸟沿着固定路线南北往返，跨越国界与大陆。迁徙通道上的湿地、滩涂是候鸟的「加油站」，一旦这些节点遭到破坏，候鸟可能因无处停歇、补给而死亡。保护候鸟，本质上是保护完整的迁徙通道网络，任何一环的缺失都可能危及全局。", "options": ["候鸟迁徙跨越国界与大陆", "迁徙通道上的湿地滩涂是候鸟的「加油站」", "保护候鸟需要保护完整的迁徙通道网络，任何一环缺失都可能危及全局", "候鸟迁徙是自然界壮观的旅程"], "answer": 2, "explanation": "文段先描述候鸟迁徙的壮观，再以「加油站」比喻迁徙节点的重要性，末句点明主旨：保护候鸟本质是保护完整的迁徙通道网络。C项完整概括。A、B、D三项都是铺垫性信息。故选C", "diff": 2},{"id": "yy-8080", "module": "yanyu", "prompt": "这段文字意在强调：数据要素市场化配置改革正在多地铺开，数据交易所如雨后春笋般设立。不过，交易所「挂牌多、成交少」的现象也暴露出供需错配的问题：企业不知道什么数据能交易、怎么交易，数据供给方则担心交易后失去控制权。破题之道，在于完善数据产权制度与交易规则，让供需双方都「敢交易、会交易」。", "options": ["应完善数据产权制度与交易规则，破解数据交易供需错配问题", "数据交易所如雨后春笋般设立", "数据要素市场化配置改革正在推进", "数据交易所存在「挂牌多、成交少」现象"], "answer": 0, "explanation": "文段先介绍数据交易所的设立，再指出「挂牌多、成交少」背后的供需错配问题，末句以「破题之道」提出对策：完善产权制度与交易规则。C项准确概括意图。A、B两项是背景；D项是问题表现。故选A", "diff": 2},{"id": "yy-8081", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：基层减负要______见效，不能以「留痕」代替「落实」，更不能让干部把精力耗在填表报数上。", "options": ["脚踏实地", "真抓实干", "实事求是", "真刀真枪"], "answer": 1, "explanation": "「真抓实干」指真正地抓、踏实地干，与后文「不能以留痕代替落实」形成对照，强调实效。「真刀真枪」多形容斗争激烈或动真格，与「见效」搭配生硬；「实事求是」指按实际情况办事，强调「求实」而非「实干」；「脚踏实地」形容做事踏实，未突出「抓落实」的动作性。故选B", "diff": 2},{"id": "yy-8082", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：面对新技术新业态，监管既要守住安全底线，也要保持______，给创新留出成长空间。", "options": ["包容审慎", "放任自流", "严防死守", "循规蹈矩"], "answer": 0, "explanation": "「包容审慎」是新技术监管的规范表述：既「包容」创新，又「审慎」把关，与「守住底线、留出空间」的辩证要求完全对应。「放任自流」指不加约束，与「守住底线」矛盾；「严防死守」只有「管」没有「容」；「循规蹈矩」指遵守成规，与监管语境不符。故选A", "diff": 2},{"id": "yy-8083", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：乡村振兴，产业是基础，人才是______。没有人才的支撑，产业发展就是无源之水。", "options": ["保障", "关键", "根本", "前提"], "answer": 1, "explanation": "「人才是关键」与「产业是基础」对举，且后文「没有人才的支撑……无源之水」强调人才的决定性作用，「关键」最贴切。「根本」强调本质与源头，与「基础」语义重叠；「前提」强调逻辑先在性，与语境不符；「保障」强调支撑作用，程度不足。故选B", "diff": 2},{"id": "yy-8084", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：城市更新中，要______大拆大建，多采用「绣花」功夫的微改造，让城市留下记忆、记住乡愁。", "options": ["舍弃", "抛弃", "放弃", "摒弃"], "answer": 3, "explanation": "「摒弃」指舍弃、排除，多与「观念、方式、陋习」等抽象事物搭配，语体庄重，与「大拆大建」的改造方式搭配规范。「抛弃」多与人或具体事物断绝关系；「放弃」指主动不再坚持，语义较轻；「舍弃」指舍去，语体偏口语。故选D", "diff": 2},{"id": "yy-8085", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：政务服务平台要打破数据壁垒，实现部门间信息______，让群众办事「最多跑一次」。", "options": ["互通共享", "上传下达", "交流沟通", "互通有无"], "answer": 0, "explanation": "「互通共享」指信息相互连通、共同使用，是政务数据共享的规范表述，与「打破数据壁垒」「最多跑一次」的语境契合。「互通有无」指各自拿出自己多余的东西交换，多用于物资；「交流沟通」偏人际交流；「上传下达」指上级政策下传、下级情况上报，与数据共享语境不符。故选A", "diff": 2},{"id": "yy-8086", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：文化遗产保护需要______，既要有专业机构的科学评估，也要有普通民众的广泛参与，形成保护合力。", "options": ["单打独斗", "多方联动", "一呼百应", "各自为政"], "answer": 1, "explanation": "「多方联动」指多个主体协同行动，与后文「专业机构+普通民众」「形成保护合力」的语境一致。「单打独斗」「各自为政」都与「合力」相悖；「一呼百应」形容响应者众多，强调「号召力」而非「协同机制」。故选B", "diff": 2},{"id": "yy-8087", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：优化营商环境，要______企业急难愁盼，把政策送到企业心坎上，让企业轻装上阵。", "options": ["聚焦", "瞄准", "注视", "对准"], "answer": 0, "explanation": "「聚焦」比喻把注意力集中到重点上，与「急难愁盼」搭配是政务语境的规范用法。「瞄准」「对准」偏具体动作，语体过于形象；「注视」指目光注视，与抽象问题搭配不当。故选A", "diff": 2},{"id": "yy-8088", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：生态修复不能______，要尊重自然规律，宜林则林、宜草则草、宜湿则湿。", "options": ["因地制宜", "因势利导", "揠苗助长", "顺其自然"], "answer": 2, "explanation": "「揠苗助长」比喻违反事物发展规律急于求成，与后文「尊重自然规律」「宜林则林」的分区施策形成对照。「顺其自然」「因势利导」「因地制宜」都是顺应规律的做法，与文意相悖。故选C", "diff": 2},{"id": "yy-8089", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：历史街区改造，要______历史文脉，避免「千街一面」，让老街区既有烟火气，又有文化味。", "options": ["继承", "延续", "保留", "沿袭"], "answer": 1, "explanation": "「延续」指照原样持续下去，与「文脉」搭配自然，强调文脉的动态传承。「继承」多与「遗产、事业」搭配，主体多为人；「沿袭」多与「制度、旧例」搭配，含因循色彩；「保留」指保持不变，缺少「传承发展」的动态感。故选B", "diff": 2},{"id": "yy-8090", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：面对群众的急难愁盼，党员干部要______，把群众的「小事」当作自己的「大事」来办。", "options": ["推己及人", "将心比心", "设身处地", "换位思考"], "answer": 1, "explanation": "「将心比心」指拿自己的心去比照别人的心，强调以真心换真心，与「把群众的小事当作自己的大事」的语境契合。「设身处地」「换位思考」都强调「站在对方角度想」，侧重认知层面；「推己及人」指用自己的心意推想别人的心意，侧重「体谅」。故选B", "diff": 2},{"id": "yy-8091", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：科技伦理治理要______，既不能因噎废食阻碍创新，也不能放任技术滥用危害社会。", "options": ["宽严皆误", "从严从紧", "审慎平衡", "大胆推进"], "answer": 2, "explanation": "「审慎平衡」指谨慎地把握尺度、兼顾各方，与后文「既不能……也不能……」的辩证要求一致。「大胆推进」与「不能放任滥用」矛盾；「从严从紧」与「不能因噎废食」矛盾；「宽严皆误」是对结果的描述，不是治理态度。故选C", "diff": 2},{"id": "yy-8092", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：发展新质生产力，要______传统产业升级和新兴产业培育，两手抓、两手硬。", "options": ["统筹推进", "重点突破", "分别处理", "优先发展"], "answer": 0, "explanation": "「统筹推进」指统一筹划、协同推进，与「两手抓、两手硬」的并重要求一致。「分别处理」缺少「协同」之意；「优先发展」「重点突破」都强调「偏重一方」，与「两手硬」矛盾。故选A", "diff": 2},{"id": "yy-8093", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：基层治理要______，既发挥党组织领导作用，又激发居民自治活力，共建共治共享。", "options": ["一元主导", "多元共治", "分散治理", "单向管理"], "answer": 1, "explanation": "「多元共治」指多个主体共同参与治理，与「党组织+居民自治」「共建共治共享」的语境一致。「一元主导」只强调一方；「单向管理」是传统模式，与「共治」相悖；「分散治理」与「共建共治」矛盾。故选B", "diff": 2},{"id": "yy-8094", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：政务公开要______，公开前做好解读，公开后及时回应，让群众看得懂、用得上、能监督。", "options": ["全程规范", "全程留痕", "全程公开", "全程参与"], "answer": 0, "explanation": "「全程规范」指公开的每个环节都依规进行，涵盖「解读—回应—监督」的全链条要求。「全程留痕」侧重记录，与「让群众看得懂」无关；「全程公开」与「政务公开」语义重复；「全程参与」主体错位，公开的对象是群众而非公开本身。故选A", "diff": 2},{"id": "yy-8095", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：应对人口老龄化，要______养老事业和养老产业，既保基本、兜底线，又扩供给、提质量。", "options": ["优先发展", "分别发展", "协同发展", "重点发展"], "answer": 2, "explanation": "「协同发展」指相互协作、共同发展，与「既保基本又扩供给」的并重要求一致。「分别发展」缺少「协同」；「优先发展」「重点发展」都强调「偏重一方」，与「两手抓」的语境矛盾。故选C", "diff": 2},{"id": "yy-8096", "module": "yanyu", "prompt": "这段文字主要说明：随着直播经济的兴起，一批「网红打卡地」带动了县域旅游。不过，流量退潮后，一些地方暴露出接待能力不足、服务标准缺失、同质化严重等问题。旅游经济的持久动力，不在一时的流量，而在扎实的供给——把交通、住宿、餐饮、体验等基础服务做扎实，才能把「网红」变「长红」。", "options": ["流量是县域旅游发展的持久动力", "「网红打卡地」带动了县域旅游发展", "县域旅游要从「网红」变「长红」，关键在扎实供给", "县域旅游存在接待能力不足等问题"], "answer": 2, "explanation": "文段先介绍「网红打卡地」带火县域旅游，再指出流量退潮后的问题，末句点明主旨：持久动力在扎实供给，才能「网红」变「长红」。C项完整概括。A、B两项分别是背景与问题；D项与文意相反。故选C", "diff": 2},{"id": "yy-8097", "module": "yanyu", "prompt": "这段文字意在强调：人工智能大模型的训练离不开海量数据，但网络数据的质量参差不齐，错误信息、偏见内容可能被模型「照单全收」。为此，研究者提出多种对齐方法，让模型输出与人类价值观对齐。技术向善，不能只靠模型「自觉」，更要靠数据治理与价值对齐的双重把关。", "options": ["大模型训练需要海量数据", "人工智能大模型存在偏见风险", "网络数据质量参差不齐", "大模型的价值对齐需要数据治理与技术手段双重把关"], "answer": 3, "explanation": "文段先指出大模型训练面临的数据质量问题，再介绍对齐方法，末句以「不能只靠……更要靠……」点明意图：数据治理与价值对齐双重把关。C项准确概括。A、B、D三项都是文段的部分信息。故选D", "diff": 2},{"id": "yy-8098", "module": "yanyu", "prompt": "这段文字主要说明：随着城市更新推进，工业遗产改造成为热点。老厂房变身创意园区、旧车间改成美术馆，工业记忆与现代生活交融。不过，改造中也出现了「重商业轻文化」的倾向——一些园区把工业遗存当作背景板，商业业态喧宾夺主，工业文脉反而被稀释。工业遗产改造，要在商业与文化之间找到平衡。", "options": ["工业文脉是城市记忆的重要组成部分", "工业遗产改造出现「重商业轻文化」倾向，应在商业与文化间找平衡", "创意园区是工业遗产改造的主要方向", "工业遗产改造让老厂房焕发新生"], "answer": 1, "explanation": "文段先介绍工业遗产改造的实践，转折后指出「重商业轻文化」的问题，末句提出应在商业与文化之间找平衡。B项完整概括。A项是背景；C项「主要方向」文中未比较；D项文中未展开。故选B", "diff": 2},{"id": "yy-8099", "module": "yanyu", "prompt": "这段文字意在强调：基层是社会治理的基础，也是政策落实的「最后一公里」。基层干部身处一线，最了解群众需求，也最清楚政策落地的堵点。给基层更多自主空间，鼓励基层探索创新，才能让政策更接地气，让治理更有温度。上级部门要善于倾听基层声音，把基层的好经验、好做法及时总结推广。", "options": ["应给基层更多自主空间，鼓励探索创新并总结推广好经验", "基层治理面临诸多困难", "基层是政策落实的「最后一公里」", "基层干部最了解群众需求"], "answer": 0, "explanation": "文段先阐述基层与基层干部的重要性，再以「给基层更多自主空间，鼓励探索创新」提出核心主张，末句进一步强调上级要倾听、总结、推广。C项完整概括意图。A、B两项是铺垫；D项文中未展开。故选A", "diff": 2},{"id": "yy-8100", "module": "yanyu", "prompt": "这段文字主要说明：随着「银发列车」的开行，老年游客组团出游日益常见。不过，老年旅游市场也存在「低价团」诱导购物、行程安排忽视老年人身体状况等问题。规范老年旅游市场，既要加强监管，也要鼓励适老化产品创新，让老年人游得放心、玩得舒心。", "options": ["「银发列车」的开行方便了老年游客出游", "老年旅游市场需要加强监管与适老化产品创新并举", "老年旅游市场存在「低价团」诱导购物等问题", "老年人出游意愿不断增强"], "answer": 1, "explanation": "文段先介绍老年旅游的兴起，再指出市场存在的问题，末句提出规范之道：加强监管与鼓励适老化产品创新。C项完整概括。A、D两项是背景；B项只是问题部分。故选B", "diff": 2},{"id": "yy-8101", "module": "yanyu", "prompt": "这段文字意在强调：古籍数字化让珍贵典籍「触手可及」，读者足不出户即可翻阅善本。不过，数字化不是把古籍拍成图片那么简单。古籍数字化要遵循版本学原则，对不同版本进行甄别、著录，才能保证数字资源的学术价值。同时，要建立统一的标准与共享平台，避免「数据孤岛」。", "options": ["古籍数字化要遵循版本学原则，并建立统一标准与共享平台", "古籍数字化需要大量资金投入", "古籍数字化让典籍「触手可及」", "古籍数字化可以完全替代原件阅览"], "answer": 0, "explanation": "文段先介绍古籍数字化的便利，转折后指出数字化并非简单拍照，进而提出两点要求：遵循版本学原则、建立统一标准与共享平台。B项完整概括意图。A项是背景；C项文中未提；D项「完全替代」文中未说且表述绝对。故选A", "diff": 2},{"id": "yy-8102", "module": "yanyu", "prompt": "这段文字主要说明：近年来，一些地方探索「信用修复」机制，失信主体在纠正失信行为、消除不良影响后，可申请移出失信名单。信用修复不是给失信「翻篇」，而是给改过者「开前门」，激励失信主体主动纠错、重塑信用。当然，信用修复也要防止被滥用，修复条件、修复程序都要严格规范。", "options": ["「信用修复」机制在多地探索推行", "信用体系建设不断完善", "失信主体纠正失信行为后可申请移出失信名单", "信用修复给失信主体改过机会，但要严格规范防止滥用"], "answer": 3, "explanation": "文段先介绍信用修复机制，再以「不是……而是……」阐明其意义，末句以「当然」转折强调要防止滥用、严格规范。B项完整概括。A、C两项是背景介绍；D项文中未展开。故选D", "diff": 2},{"id": "yy-8103", "module": "yanyu", "prompt": "这段文字意在强调：城市「一刻钟便民生活圈」建设让居民在家门口享受便利。不过，便民商圈不能只有连锁品牌，也要给「小修小补」留位置——配钥匙、修鞋、改衣服，这些看似不起眼的服务，恰恰是居民日常所需。城市治理要有温度，让便民服务既有「颜值」又有「烟火气」。", "options": ["便民商圈应兼顾连锁品牌与「小修小补」，让城市治理更有温度", "「一刻钟便民生活圈」建设让居民享受便利", "连锁品牌提升了便民商圈的品质", "「小修小补」是居民日常所需"], "answer": 0, "explanation": "文段先介绍便民生活圈建设，转折后指出不能只有连锁品牌、要给「小修小补」留位置，末句点明意图：城市治理要有温度。C项完整概括。A、B两项是铺垫；D项文中未比较。故选A", "diff": 2},{"id": "yy-8104", "module": "yanyu", "prompt": "这段文字主要说明：随着新能源汽车保有量攀升，废旧动力电池回收问题日益凸显。电池中含有锂、钴、镍等金属，回收利用价值高，但若处置不当，也存在环境污染风险。当前，正规回收渠道与「黑作坊」并存，后者以高价抢货、粗放拆解，扰乱市场秩序。完善回收体系，要让正规渠道「接得住」，也要让「黑作坊」无处遁形。", "options": ["废旧动力电池回收需要完善正规渠道并打击「黑作坊」", "动力电池中的金属资源具有回收价值", "新能源汽车保有量不断攀升", "废旧动力电池回收利用价值高但处置不当有污染风险"], "answer": 0, "explanation": "文段先介绍电池回收的背景与价值、风险，再指出正规渠道与「黑作坊」并存的乱象，末句提出完善回收体系的两手：让正规渠道接得住、让黑作坊无处遁形。C项完整概括。A、B、D三项都是铺垫信息。故选A", "diff": 2},{"id": "yy-8105", "module": "yanyu", "prompt": "这段文字意在强调：随着「国货潮」兴起，一批老字号品牌焕发新生。不过，老字号创新不能丢掉「看家本领」——传统工艺、经典配方、诚信口碑是老字号的立身之本。创新是让传统更好地走进现代生活，而不是把传统改得面目全非。老字号要在守正与创新之间找到平衡点。", "options": ["「国货潮」让老字号品牌焕发新生", "老字号要在守正与创新之间找到平衡点", "老字号创新不能丢掉传统", "老字号的立身之本是传统工艺、经典配方、诚信口碑"], "answer": 1, "explanation": "文段先介绍老字号焕发新生，再指出创新不能丢掉「看家本领」，末句点明主旨：要在守正与创新之间找到平衡点。C项准确概括意图。A、B两项是铺垫；D项只是部分观点，缺少「创新」一面的平衡表达。故选B", "diff": 2},{"id": "yy-8106", "module": "yanyu", "prompt": "这段文字主要说明：随着城市养宠人群增多，宠物诊疗机构快速扩张。不过，行业快速发展的背后，也存在收费不透明、从业人员资质参差、诊疗纠纷频发等问题。规范宠物诊疗市场，既要完善行业标准与监管机制，也要畅通消费者维权渠道，让人与宠物都能得到善待。", "options": ["宠物诊疗纠纷频发影响行业声誉", "宠物诊疗市场需要完善标准监管与畅通维权渠道并举", "宠物诊疗机构快速扩张", "城市养宠人群不断增加"], "answer": 1, "explanation": "文段先介绍宠物诊疗机构的扩张，再指出行业存在的问题，末句提出规范之道：完善标准监管与畅通维权渠道。C项完整概括。A、B两项是背景；D项只是问题的部分表现。故选B", "diff": 2},{"id": "yy-8107", "module": "yanyu", "prompt": "这段文字意在强调：随着人口流动加速，「跨省通办」政务服务事项不断扩围。不过，跨省通办不能只停留在「能办」，还要向「好办」「易办」升级——优化办事流程、统一办理标准、推动数据共享，让群众异地办事像本地一样便捷。政务服务改革，要以群众视角审视每一个环节。", "options": ["数据共享是跨省通办的技术支撑", "「跨省通办」政务服务事项不断扩围", "跨省通办要从「能办」向「好办」「易办」升级，以群众视角优化服务", "政务服务改革取得显著成效"], "answer": 2, "explanation": "文段先介绍跨省通办的扩围，转折后提出「不能只停留在能办，还要向好办易办升级」，末句点明要以群众视角审视环节。B项完整概括意图。A、D两项是背景；C项只是举措之一。故选C", "diff": 2},{"id": "yy-8108", "module": "yanyu", "prompt": "这段文字主要说明：随着研学旅行升温，一批「研学基地」应运而生。不过，部分基地「游而不学」或「学而不游」——有的只组织观光，缺乏课程设计；有的照搬课堂，忽视体验。研学旅行的核心是「研」与「学」，要在「游」中设计问题、在「行」中寻找答案，让课程与体验深度融合。", "options": ["研学旅行市场持续升温", "研学基地存在「游而不学」或「学而不游」问题", "研学基地的课程设计能力有待提升", "研学旅行要实现课程与体验深度融合，突出「研」与「学」的核心"], "answer": 3, "explanation": "文段先介绍研学旅行升温，再指出基地的两类问题，末句点明核心：研学旅行的核心是「研」与「学」，要课程与体验融合。C项完整概括。A项是背景；B项是问题；D项只是问题的部分对策。故选D", "diff": 2},{"id": "yy-8109", "module": "yanyu", "prompt": "这段文字意在强调：随着智慧城市建设推进，城市大脑在交通疏导、应急指挥等方面发挥重要作用。不过，技术不是万能的，城市治理的核心是人。智慧城市要避免「重技术轻人文」——数据再多、算法再强，如果不能回应市民的真实需求，就难以赢得认同。智慧城市的最终尺度，是人的获得感、幸福感、安全感。", "options": ["市民对智慧城市的认同度有待提升", "技术是智慧城市建设的重要支撑", "智慧城市要避免「重技术轻人文」，以人的获得感为最终尺度", "城市大脑在交通、应急等方面发挥重要作用"], "answer": 2, "explanation": "文段先介绍城市大脑的作用，转折后指出「技术不是万能的，城市治理的核心是人」，末句点明智慧城市的最终尺度是人的获得感。B项完整概括意图。A、C两项是铺垫；D项文中未展开。故选C", "diff": 2},{"id": "yy-8110", "module": "yanyu", "prompt": "这段文字主要说明：随着「双11」临近，各大电商平台纷纷推出预售、满减、直播带货等玩法。不过，复杂的优惠规则让不少消费者直呼「烧脑」——定金不退、先涨后降、优惠叠加限制多，购物体验大打折扣。促销的本质是让利消费者，规则宜简不宜繁，让消费者明明白白消费，才能赢得长久信任。", "options": ["复杂优惠规则让消费者购物体验大打折扣", "「双11」各大电商平台推出多种促销玩法", "电商促销规则宜简不宜繁，要让消费者明白消费", "直播带货成为电商促销的重要形式"], "answer": 2, "explanation": "文段先介绍电商促销玩法，再指出复杂规则带来的问题，末句点明主旨：促销本质是让利，规则宜简不宜繁。C项完整概括。A、B、D三项都是铺垫或问题。故选C", "diff": 2},{"id": "yy-8111", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：政务服务要______群众视角，把「麻烦」留给自己，把「方便」让给群众。", "options": ["立足", "坚持", "秉持", "站稳"], "answer": 3, "explanation": "「站稳群众视角」强调以群众立场为根本立场，与后文「把麻烦留给自己、把方便让给群众」的立场表达一致。「立足」多与「实际、当下」搭配；「坚持」多与「原则、方向」搭配；「秉持」多与「理念、原则」搭配，与「视角」搭配生硬。故选D", "diff": 2},{"id": "yy-8112", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：基层治理要______，既要发挥党组织领导作用，又要激发居民自治活力。", "options": ["双向发力", "单向推进", "多头管理", "分散治理"], "answer": 0, "explanation": "「双向发力」指两个方向同时用力，与「既要……又要……」的并重结构一致。「单向推进」只强调一个方向；「多头管理」指管理主体混乱，含贬义；「分散治理」与「共建共治」相悖。故选A", "diff": 2},{"id": "yy-8113", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：历史文化遗产保护要______，不能今天修、明天拆，更不能拆真古董、建假古董。", "options": ["久久为功", "一劳永逸", "朝令夕改", "急功近利"], "answer": 0, "explanation": "「久久为功」指持之以恒、长期坚持，与「不能今天修、明天拆」的稳定要求一致。「朝令夕改」指经常改变命令，含贬义，与文意相悖；「急功近利」指急于求成，与「保护」的长期性矛盾；「一劳永逸」指一次努力永久受益，与保护的持续性不符。故选A", "diff": 2},{"id": "yy-8114", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：优化营商环境，要______企业诉求，建立常态化政企沟通机制，让企业反映问题有渠道、解决问题有回应。", "options": ["拓宽", "打通", "开放", "畅通"], "answer": 3, "explanation": "「畅通诉求」指让诉求表达渠道顺畅无阻，与后文「有渠道、有回应」的机制性表达一致。「打通」多与「壁垒、堵点」搭配；「开放」多与「平台、渠道」搭配，强调「允许进入」；「拓宽」多与「渠道」搭配，与「诉求」搭配不当。故选D", "diff": 2},{"id": "yy-8115", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：乡村振兴要______，既发展特色产业，又保护生态环境，实现经济效益与生态效益双赢。", "options": ["统筹兼顾", "量力而行", "顾此失彼", "权衡利弊"], "answer": 0, "explanation": "「统筹兼顾」指统一筹划、全面照顾，与「既发展产业又保护生态」「双赢」的要求一致。「顾此失彼」指不能全面照顾，与文意相悖；「权衡利弊」强调「选择」而非「兼顾」；「量力而行」指按自身力量行事，与语境不符。故选A", "diff": 2},{"id": "yy-8116", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：面对新形势新任务，党员干部要______，不断学习新知识、掌握新技能，避免本领恐慌。", "options": ["因循守旧", "墨守成规", "固步自封", "与时俱进"], "answer": 3, "explanation": "「与时俱进」指随着时代发展而不断进步，与「不断学习新知识、掌握新技能」的要求一致。「因循守旧」「墨守成规」「固步自封」都指守旧不变，与文意相悖。故选D", "diff": 2},{"id": "yy-8117", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：基层减负要______，既要精简文件会议，又要规范督查考核，从源头上减轻基层负担。", "options": ["头痛医头", "治标不治本", "脚痛医脚", "标本兼治"], "answer": 3, "explanation": "「标本兼治」指既解决表面问题又解决根本问题，与「既要精简又要规范」「从源头减轻」的要求一致。「治标不治本」「头痛医头」「脚痛医脚」都指只处理表面问题，与文意相悖。故选D", "diff": 2},{"id": "yy-8118", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：政务新媒体要______，不能只发布、不互动，更不能「僵尸化」运营。", "options": ["按部就班", "照常运转", "良性运转", "正常发布"], "answer": 2, "explanation": "「良性运转」指运行状态良好、有互动有实效，与「不能只发布不互动」「不能僵尸化」的要求一致。「照常运转」「正常发布」都只强调「正常」，未体现「良性」；「按部就班」指按规矩办事，与「互动性」无关。故选C", "diff": 2},{"id": "yy-8119", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：发展数字经济，要______数据安全与发展效率，既防范风险，又释放数据价值。", "options": ["权衡利弊", "有所取舍", "顾此失彼", "统筹平衡"], "answer": 3, "explanation": "「统筹平衡」指统一筹划、把握平衡，与「既防范风险又释放价值」的并重要求一致。「顾此失彼」指不能全面照顾，与文意相悖；「权衡利弊」强调「选择」而非「平衡」；「有所取舍」指放弃一方，与「既要又要」矛盾。故选D", "diff": 2},{"id": "yy-8120", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：城市治理要______，既要运用大数据提升效率，也要保留城市的「烟火气」与人文关怀。", "options": ["以刚为主", "刚柔并济", "以柔克刚", "外柔内刚"], "answer": 1, "explanation": "「刚柔并济」指刚与柔相互补充、相得益彰，与「既要技术效率也要人文关怀」的并重结构一致。「以刚为主」偏重一方；「以柔克刚」指用柔弱胜刚强，与语境不符；「外柔内刚」形容人的性格，与治理语境无关。故选B", "diff": 2},{"id": "yy-8121", "module": "yanyu", "prompt": "这段文字主要说明：随着城市夜间经济兴起，夜市摊位成为灵活就业的重要载体。不过，夜市繁荣的背后，也存在占道经营、噪音扰民、油烟污染等问题。治理夜市，不能「一禁了之」，也不能「放任不管」，要在规范与活力之间找到平衡点，让城市烟火气与文明范儿兼得。", "options": ["夜市摊位是灵活就业的重要载体", "城市夜间经济日益繁荣", "夜市存在占道经营、噪音扰民等问题", "夜市治理要在规范与活力之间找到平衡点"], "answer": 3, "explanation": "文段先介绍夜市的就业价值，再指出存在的问题，末句点明主旨：治理不能一禁了之也不能放任不管，要在规范与活力之间找平衡。C项完整概括。A、B两项是铺垫；D项是背景。故选D", "diff": 2},{"id": "yy-8122", "module": "yanyu", "prompt": "这段文字意在强调：随着人口老龄化加深，适老化改造需求日益迫切。不过，目前适老化改造多集中在家庭内部，公共空间的适老化仍显不足——盲道被占、坡道缺失、标识不清，让老年人出行「步步惊心」。适老化改造要从家庭走向城市，让公共空间对老年人更友好。", "options": ["人口老龄化程度不断加深", "盲道被占、坡道缺失等问题影响老年人出行", "适老化改造要从家庭走向城市，补齐公共空间的短板", "适老化改造多集中在家庭内部"], "answer": 2, "explanation": "文段先介绍适老化改造需求，再指出公共空间适老化不足的问题，末句点明意图：适老化改造要从家庭走向城市。C项完整概括。A、B、D三项都是铺垫或问题。故选C", "diff": 2},{"id": "yy-8123", "module": "yanyu", "prompt": "这段文字主要说明：随着「双碳」目标推进，绿色建筑快速发展。不过，部分绿色建筑存在「重设计轻运营」的问题——设计阶段拿到绿色认证，运营阶段却能耗居高不下。绿色建筑的价值在于全生命周期的节能减排，运营阶段的精细化管理不可或缺。让绿色建筑真正「绿」起来，要设计、运营两手抓。", "options": ["绿色建筑快速发展", "绿色建筑要设计、运营两手抓，实现全生命周期节能减排", "部分绿色建筑存在「重设计轻运营」问题", "绿色建筑认证体系有待完善"], "answer": 1, "explanation": "文段先介绍绿色建筑的发展，再指出「重设计轻运营」的问题，末句点明主旨：设计、运营两手抓，实现全生命周期节能减排。C项完整概括。A项是背景；B项是问题；D项文中未展开。故选B", "diff": 2},{"id": "yy-8124", "module": "yanyu", "prompt": "这段文字意在强调：随着直播带货兴起，农产品销售渠道不断拓宽。不过，直播助农不能只靠「悲情营销」——一些主播夸大滞销、卖惨带货，透支了消费者信任。直播助农要走远，关键在产品本身：把好质量关、做好供应链，让消费者买到好产品，才能形成复购与口碑。", "options": ["消费者对直播助农的信任度下降", "一些主播夸大滞销、卖惨带货透支信任", "直播带货拓宽了农产品销售渠道", "直播助农要走远，关键在产品质量与供应链"], "answer": 3, "explanation": "文段先介绍直播助农的兴起，再指出「悲情营销」的问题，末句点明意图：关键在产品本身——质量与供应链。C项完整概括。A、B两项是铺垫；D项文中未展开。故选D", "diff": 2},{"id": "yy-8125", "module": "yanyu", "prompt": "这段文字主要说明：随着城市更新推进，「口袋公园」成为市民家门口的绿色福利。不过，一些口袋公园建成后缺乏管护，设施损坏无人修、绿化退化无人管，市民从欣喜到惋惜。公园建设「三分建、七分管」，长效管护机制不可或缺，要让口袋公园不仅建得好，更管得好。", "options": ["「口袋公园」成为市民家门口的绿色福利", "口袋公园建设投入逐年增加", "口袋公园要建管并重，建立长效管护机制", "一些口袋公园建成后缺乏管护"], "answer": 2, "explanation": "文段先介绍口袋公园的建设成效，再指出缺乏管护的问题，末句点明主旨：建管并重、长效管护。C项完整概括。A、B两项是铺垫；D项文中未提。故选C", "diff": 2},{"id": "yy-8126", "module": "yanyu", "prompt": "这段文字意在强调：随着人工智能技术发展，AI换脸、AI拟声等应用层出不穷。不过，技术滥用也带来风险——有人利用AI换脸实施诈骗，有人用AI拟声冒充他人。技术本身无善恶，关键在用的人。治理AI滥用，既要完善立法，也要提升公众的识别能力，让技术向善不向恶。", "options": ["治理AI滥用要完善立法与提升公众识别能力并举", "AI技术滥用带来诈骗等风险", "AI换脸、AI拟声等应用层出不穷", "AI技术本身无善恶，关键在使用者"], "answer": 0, "explanation": "文段先介绍AI应用的发展，再指出滥用风险，末句提出治理之道：完善立法与提升公众识别能力并举。C项完整概括意图。A、B两项是铺垫；D项是文段的部分观点，缺少「治理」的对策表达。故选A", "diff": 2},{"id": "yy-8127", "module": "yanyu", "prompt": "这段文字主要说明：随着新能源汽车保有量攀升，充电难成为车主的「心病」。不过，充电难不只是充电桩数量问题——有的小区电容不足装不了桩，有的高速服务区节假日排队严重，有的充电桩坏了没人修。破解充电难，要数量、布局、运维三管齐下，让车主充得上电、充得放心。", "options": ["节假日高速服务区充电排队严重", "新能源汽车保有量不断攀升", "充电难不只是充电桩数量问题", "破解充电难要数量、布局、运维三管齐下"], "answer": 3, "explanation": "文段先介绍充电难的背景，再指出充电难的多重原因，末句点明主旨：数量、布局、运维三管齐下。C项完整概括。A项是背景；B项是问题分析；D项只是问题的一个表现。故选D", "diff": 2},{"id": "yy-8128", "module": "yanyu", "prompt": "这段文字意在强调：随着「双减」政策落地，学科类培训大幅压减。不过，一些隐形变异培训转入地下——「一对一」家教、住家教师、「众筹私教」等违规培训时有发生。治理隐形变异培训，不能只靠突击检查，还要健全长效监管机制，同时满足家长对优质教育资源的真实需求。", "options": ["「双减」政策落地后学科类培训大幅压减", "隐形变异培训时有发生", "治理隐形变异培训要健全长效监管机制并满足真实教育需求", "家长对优质教育资源的需求客观存在"], "answer": 2, "explanation": "文段先介绍「双减」成效，再指出隐形变异培训的问题，末句提出治理之道：健全长效监管机制并满足真实需求。C项完整概括意图。A、B两项是铺垫；D项只是背景。故选C", "diff": 2},{"id": "yy-8129", "module": "yanyu", "prompt": "这段文字主要说明：随着老龄化加深，「老楼加装电梯」成为不少老旧小区的迫切需求。不过，加装电梯常因低层住户反对而搁浅——采光受影响、噪音干扰、房屋贬值担忧，都是低层住户的现实顾虑。破解僵局，既要有「一票否决」的规则约束，也要有利益协调的智慧，让高低层住户的诉求都能被看见。", "options": ["低层住户的顾虑有其现实合理性", "加装电梯常因低层住户反对而搁浅", "老楼加装电梯是老旧小区的迫切需求", "破解加装电梯僵局需要规则约束与利益协调并举"], "answer": 3, "explanation": "文段先介绍加装电梯的需求，再指出低层住户反对的僵局，末句提出破解之道：规则约束与利益协调并举。C项完整概括。A、B两项是铺垫；D项是问题分析。故选D", "diff": 2},{"id": "yy-8130", "module": "yanyu", "prompt": "这段文字意在强调：随着「国潮」兴起，一批老字号品牌焕发新生。不过，也有老字号「躺在功劳簿上吃老本」，产品创新滞后、营销方式陈旧，逐渐被市场边缘化。老字号的价值在「老」，出路在「新」——既要守住传统工艺的根，也要拥抱新消费群体，让老品牌讲出新故事。", "options": ["「国潮」兴起让老字号焕发新生", "老字号要守正创新，让老品牌讲出新故事", "一些老字号产品创新滞后、营销方式陈旧", "老字号的价值在于其悠久历史"], "answer": 1, "explanation": "文段先介绍老字号焕发新生，再指出部分老字号的困境，末句点明意图：老字号要守正创新。C项完整概括。A、B两项是铺垫；D项只是背景。故选B", "diff": 2},{"id": "yy-8131", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：政务服务要______，让数据多跑路、群众少跑腿，切实提升办事效率。", "options": ["减少服务", "提质增效", "降低标准", "提高成本"], "answer": 1, "explanation": "「提质增效」指提升质量、增加效率，与「让数据多跑路、群众少跑腿」「提升办事效率」的要求一致。「提高成本」「降低标准」「减少服务」都与「提升效率」的语境相悖。故选B", "diff": 2},{"id": "yy-8132", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：面对群众诉求，党员干部要______，把群众的「小事」当作自己的「大事」来办。", "options": ["设身处地", "推己及人", "换位思考", "将心比心"], "answer": 3, "explanation": "「将心比心」指拿自己的心去比照别人的心，强调以真心换真心，与「把群众的小事当作自己的大事」的语境契合。「设身处地」「换位思考」都强调「站在对方角度想」，侧重认知层面；「推己及人」指用自己的心意推想别人的心意，侧重「体谅」。故选D", "diff": 2},{"id": "yy-8133", "module": "yanyu", "prompt": "①社区食堂火了，但「办得快」更要「办得久」。②一些社区食堂开业时红红火火，几个月后却因客源不足、成本高企而关门。③要让社区食堂可持续运营，关键在于精准定位。④既服务老年人，也向周边上班族、租户开放，用市场化收入反哺公益属性。⑤政府则应在场地租金、水电费用上给予适度支持。将以上句子重新排列，语序正确的是：", "options": ["①②③④⑤", "①③②④⑤", "②①③④⑤", "②③①④⑤"], "answer": 0, "explanation": "①提出「办得快更要办得久」的话题，②举例说明一些食堂关门的现象，③提出可持续运营的关键，④说明精准定位的具体做法，⑤补充政府的支持措施。逻辑为：话题—现象—关键—做法—补充。B项以②的现象开头缺少①的话题引入；C项③的「关键」插在②的现象前，逻辑断裂；D项③紧随②后缺少①的话题铺垫。故选A", "diff": 2},{"id": "yy-8134", "module": "yanyu", "prompt": "①数字技术为乡村治理注入新动能。②不过，一些地方出现「重建设轻运营」的问题——平台建起来了，却少人问津。③数字乡村建设要避免「面子工程」，把功夫下在实用上。④要让农民真正会用、愿意用，数字技术才能在乡村落地生根。⑤对此，应加强需求调研，让平台功能贴合农民实际需要。将以上句子重新排列，语序正确的是：", "options": ["①③②⑤④", "①②⑤③④", "①②③⑤④", "②①③⑤④"], "answer": 2, "explanation": "①提出数字技术为乡村治理注入动能的话题，②以「不过」指出「重建设轻运营」的问题，③提出要避免「面子工程」、下实用功夫，⑤以「对此」给出针对性措施——加强需求调研，④以「要让……才能……」收束展望。逻辑为：话题—问题—对策—措施—展望。B项⑤的「对此」承接③后语序颠倒，且④的收尾作用被削弱；C项以②的问题开头缺少①的铺垫；D项③插在②后打断了「问题—对策」的衔接。故选C", "diff": 2},{"id": "yy-8135", "module": "yanyu", "prompt": "①绿色低碳发展不是要限制发展，而是要实现更高质量的发展。②产业转型升级是必由之路。③传统产业通过技术改造可以焕发新的生机。④新兴产业则代表未来方向，需要前瞻布局。⑤两者并举，才能构建绿色现代化的产业体系。将以上句子重新排列，语序正确的是：", "options": ["①③②④⑤", "②①③④⑤", "①②④③⑤", "①②③④⑤"], "answer": 3, "explanation": "①提出「绿色低碳发展是更高质量的发展」的总观点，②指出产业转型升级是必由之路，③说明传统产业改造的路径，④以「则」对举新兴产业的布局，⑤以「两者并举」总结收束。逻辑为：总起—路径—传统产业—新兴产业—总结。B项②作首句缺少总观点；C项③的「传统产业」缺少②的引出；D项④的「则」缺少③的对举对象。故选D", "diff": 2},{"module": "yanyu", "prompt": "城市更新不能大拆大建，要注重保留城市记忆，让老街区在改造中延续文脉、______活力。填入画横线处最恰当的一项是：", "options": ["焕发", "爆发", "散发", "迸放"], "answer": 0, "explanation": "「焕发活力」为惯用搭配，指使活力重新展现。散发多与气味、光热搭配；爆发指突然发作；迸放非惯用搭配。故选A。", "exam": "国考", "diff": 2, "id": "yy-8136"},{"module": "yanyu", "prompt": "基层干部要沉下心、扑下身，把群众的操心事、烦心事当成自己的事来______。填入画横线处最恰当的一项是：", "options": ["打理", "筹办", "办理", "操办"], "answer": 2, "explanation": "「办理」指处理具体事务，与「事」搭配恰当。打理多用于生意、生活；操办多指婚丧事宜；筹办指筹备创办。故选C。", "exam": "国考", "diff": 2, "id": "yy-8137"},{"module": "yanyu", "prompt": "科研攻关往往需要十年磨一剑的定力，任何______的急躁情绪都可能使多年积累毁于一旦。填入画横线处最恰当的一项是：", "options": ["水到渠成", "立竿见影", "急功近利", "事半功倍"], "answer": 2, "explanation": "「急功近利」指急于求成、贪图眼前利益，与「急躁情绪」呼应。立竿见影形容见效快，含褒义；事半功倍指效率高；水到渠成指条件成熟自然成功。故选C。", "exam": "国考", "diff": 2, "id": "yy-8138"},{"module": "yanyu", "prompt": "这份调查报告用大量一手数据______了「年轻人不爱做饭」的流行说法，事实远比想象复杂。填入画横线处最恰当的一项是：", "options": ["弱化", "回避", "证实", "颠覆"], "answer": 3, "explanation": "后文说「事实远比想象复杂」，说明报告推翻了这一流行说法，「颠覆」最贴切。证实与文意相反；弱化程度不够；回避与语境无关。故选D。", "exam": "国考", "diff": 2, "id": "yy-8139"},{"module": "yanyu", "prompt": "老字号要守正更要创新，在坚守品质的同时，也要主动______新的消费场景和营销方式。填入画横线处最恰当的一项是：", "options": ["拥抱", "把守", "围拢", "疏离"], "answer": 0, "explanation": "「拥抱」比喻主动接受、迎接新事物，符合创新语境。围拢、把守、疏离均与主动接纳新事物之意相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8140"},{"module": "yanyu", "prompt": "湿地保护不能只靠划保护区，还要让周边群众从保护中______，实现生态与民生双赢。填入画横线处最恰当的一项是：", "options": ["受命", "受权", "受训", "受益"], "answer": 3, "explanation": "「受益」指得到好处，与「实现生态与民生双赢」呼应。受命指接受命令；受权指被授予权力；受训指接受训练。故选D。", "exam": "国考", "diff": 2, "id": "yy-8141"},{"module": "yanyu", "prompt": "一些短视频为博眼球刻意制造冲突，这种______流量的做法终将被观众抛弃。填入画横线处最恰当的一项是：", "options": ["透支", "支取", "支付", "预支"], "answer": 0, "explanation": "「透支」比喻过度使用而损耗未来，与「终将被抛弃」的后果呼应。预支指提前支取；支取、支付为一般财务用语，无比喻义。故选A。", "exam": "国考", "diff": 2, "id": "yy-8142"},{"module": "yanyu", "prompt": "乡村振兴，关键在产业。只有产业扎根，人才才能______，乡村才有长久生机。填入画横线处最恰当的一项是：", "options": ["迁出去", "留下来", "流出去", "走出去"], "answer": 1, "explanation": "产业扎根才能吸引人才留下，「留下来」与「扎根」「长久生机」呼应。走出去、流出去、迁出去均与文意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8143"},{"module": "yanyu", "prompt": "面对突发舆情，相关部门第一时间公开信息、回应关切，才能______谣言的生存空间。填入画横线处最恰当的一项是：", "options": ["扩大", "留出", "压缩", "放宽"], "answer": 2, "explanation": "公开信息是为了减少谣言传播空间，「压缩」最贴切。放宽、扩大、留出均与目的相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8144"},{"module": "yanyu", "prompt": "古籍修复是慢工出细活的行当，修复师们______，一页纸有时要处理一整天。填入画横线处最恰当的一项是：", "options": ["精雕细琢", "大刀阔斧", "走马观花", "囫囵吞枣"], "answer": 0, "explanation": "「精雕细琢」形容做事细致认真，与「慢工出细活」「一整天」呼应。大刀阔斧形容办事果断大胆；囫囵吞枣、走马观花形容粗略。故选A。", "exam": "国考", "diff": 2, "id": "yy-8145"},{"module": "yanyu", "prompt": "平台经济健康发展离不开规范监管，也要______企业合法经营的积极性，不能一管就死。填入画横线处最恰当的一项是：", "options": ["削弱", "保护", "压制", "漠视"], "answer": 1, "explanation": "「不能一管就死」说明要兼顾监管与活力，「保护」积极性最贴切。压制、削弱、漠视均与文意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8146"},{"module": "yanyu", "prompt": "社区食堂办得好不好，居民最有发言权。服务好不好，要由群众的______来检验。填入画横线处最恰当的一项是：", "options": ["口碑", "口风", "口才", "口供"], "answer": 0, "explanation": "「口碑」指群众中的评价，与「由群众检验」呼应。口供指供述；口才指说话能力；口风指话中透露的态度。故选A。", "exam": "国考", "diff": 2, "id": "yy-8147"},{"module": "yanyu", "prompt": "数字经济浪潮下，传统制造业不是被淘汰，而是要借力______升级。填入画横线处最恰当的一项是：", "options": ["转型", "转运", "转述", "转向"], "answer": 0, "explanation": "「转型升级」为惯用搭配，指产业向高端发展。转向指改变方向；转运指运气好转或运输；转述指转达叙述。故选A。", "exam": "国考", "diff": 2, "id": "yy-8148"},{"module": "yanyu", "prompt": "垃圾分类看似小事，实则______着治理能力，考验着城市的精细化管理水平。填入画横线处最恰当的一项是：", "options": ["考量", "考验", "考察", "考查"], "answer": 1, "explanation": "句中已有「考验」，此处强调垃圾分类反映治理能力，「考量」指衡量、考虑，与前文「考验着」形成呼应且不重复。故选B。", "exam": "国考", "diff": 2, "id": "yy-8149"},{"module": "yanyu", "prompt": "文物承载灿烂文明，传承历史文化，是______不可再生的宝贵资源。填入画横线处最恰当的一项是：", "options": ["成双成对", "比比皆是", "多如牛毛", "独一无二"], "answer": 3, "explanation": "文物不可再生，强调其独特珍贵，「独一无二」最贴切。其余三项均与「不可再生」的珍稀性相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8150"},{"module": "yanyu", "prompt": "优化营商环境没有完成时，只有进行时，要______发力、久久为功。填入画横线处最恰当的一项是：", "options": ["持续", "断续", "间歇", "偶发"], "answer": 0, "explanation": "「久久为功」强调长期坚持，「持续发力」与之呼应。间歇、断续、偶发均与持续性相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8151"},{"module": "yanyu", "prompt": "面对海量信息，公众更需要______的判断力，不轻信、不盲传。填入画横线处最恰当的一项是：", "options": ["摇摆", "从众", "独立", "依附"], "answer": 2, "explanation": "「不轻信、不盲传」需要独立判断。依附、从众、摇摆均与独立判断相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8152"},{"module": "yanyu", "prompt": "老旧小区加装电梯，难在协调各方利益，关键在于______共识、找到最大公约数。填入画横线处最恰当的一项是：", "options": ["消解", "凝聚", "分散", "瓦解"], "answer": 1, "explanation": "「凝聚共识」为惯用搭配，与「找到最大公约数」呼应。分散、瓦解、消解均与形成共识之意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8153"},{"module": "yanyu", "prompt": "青年人才是创新的生力军，要为他们______成长成才的广阔舞台。填入画横线处最恰当的一项是：", "options": ["搭建", "拆毁", "封锁", "观望"], "answer": 0, "explanation": "「搭建舞台」为惯用搭配。拆毁、封锁、观望均与提供舞台之意相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8154"},{"module": "yanyu", "prompt": "网络直播带货要行稳致远，主播必须______法律底线，诚信经营。填入画横线处最恰当的一项是：", "options": ["突破", "试探", "坚守", "偏离"], "answer": 2, "explanation": "「坚守底线」为惯用搭配，与「行稳致远」「诚信经营」呼应。突破、试探、偏离均与守法之意相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8155"},{"module": "yanyu", "prompt": "这本书语言平实却______深刻，读来常有豁然开朗之感。填入画横线处最恰当的一项是：", "options": ["见效", "见闻", "见解", "见习"], "answer": 2, "explanation": "「见解深刻」为惯用搭配，指看法、认识深刻。见闻指所见所闻；见习指实习；见效指产生效果。故选C。", "exam": "国考", "diff": 2, "id": "yy-8156"},{"module": "yanyu", "prompt": "治理超载不能一阵风，要建立______机制，让守法者受益、违法者受限。填入画横线处最恰当的一项是：", "options": ["短期", "应急", "临时", "长效"], "answer": 3, "explanation": "「不能一阵风」强调长期性，「长效机制」与之呼应。短期、临时、应急均与长期性相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8157"},{"module": "yanyu", "prompt": "非遗传承不能只靠情怀，还要在市场中______，让传统技艺自身造血。填入画横线处最恰当的一项是：", "options": ["站稳脚跟", "摇摇欲坠", "销声匿迹", "节节败退"], "answer": 0, "explanation": "「自身造血」需要在市场中立足发展，「站稳脚跟」最贴切。其余三项均与生存发展之意相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8158"},{"module": "yanyu", "prompt": "政务公开的意义，在于把权力关进制度的笼子，让群众看得见、______。填入画横线处最恰当的一项是：", "options": ["无从下手", "置之不理", "望而却步", "监督得了"], "answer": 3, "explanation": "政务公开让群众能监督，「监督得了」与「看得见」形成递进。其余三项均与公开监督之意相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8159"},{"module": "yanyu", "prompt": "企业创新要敢于投入，如果总是______、患得患失，就很难有突破。填入画横线处最恰当的一项是：", "options": ["当机立断", "大刀阔斧", "雷厉风行", "畏首畏尾"], "answer": 3, "explanation": "「患得患失」与「畏首畏尾」都形容顾虑多、不敢干，语义连贯。雷厉风行、当机立断、大刀阔斧均形容果断，与文意相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8160"},{"module": "yanyu", "prompt": "生态修复非一日之功，需要一代代人______地干下去。填入画横线处最恰当的一项是：", "options": ["观望", "接续", "搁置", "中断"], "answer": 1, "explanation": "「一代代人接续」强调代际传承、不断努力。中断、搁置、观望均与持续努力之意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8161"},{"module": "yanyu", "prompt": "消费券要真正______消费潜力，发放方式就得精准，让钱花在刀刃上。填入画横线处最恰当的一项是：", "options": ["冻结", "封存", "抑制", "激活"], "answer": 3, "explanation": "「激活潜力」为惯用搭配。冻结、抑制、封存均与释放潜力之意相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8162"},{"module": "yanyu", "prompt": "学术研究要耐得住寂寞，______于热点、追逐流量，反而出不了大成果。填入画横线处最恰当的一项是：", "options": ["孜孜以求", "潜心钻研", "一味迎合", "脚踏实地"], "answer": 2, "explanation": "「反而出不了大成果」说明前文是负面做法，「一味迎合」最贴切。潜心钻研、孜孜以求、脚踏实地均为正面做法。故选C。", "exam": "国考", "diff": 2, "id": "yy-8163"},{"module": "yanyu", "prompt": "老旧厂房改造要因地制宜，不能______，把所有园区都办成一个模样。填入画横线处最恰当的一项是：", "options": ["百花齐放", "千篇一律", "因地制宜", "各具特色"], "answer": 1, "explanation": "「都办成一个模样」即千篇一律，与「因地制宜」相悖的正是千篇一律。百花齐放、各具特色与文意相悖；因地制宜是正确做法。故选B。", "exam": "国考", "diff": 2, "id": "yy-8164"},{"module": "yanyu", "prompt": "食品安全监管必须______，从田间到餐桌每个环节都不能掉链子。填入画横线处最恰当的一项是：", "options": ["全程把关", "偶尔抽查", "半途而废", "浅尝辄止"], "answer": 0, "explanation": "「从田间到餐桌每个环节」强调全过程，「全程把关」最贴切。其余三项均与全程监管之意相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8165"},{"module": "yanyu", "prompt": "志愿服务贵在______，三天打鱼两天晒网式的爱心难以持久。填入画横线处最恰当的一项是：", "options": ["临时性", "突击性", "常态化", "偶然性"], "answer": 2, "explanation": "「三天打鱼两天晒网」批评不持久，「常态化」与之相对。突击性、偶然性、临时性均与持久之意相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8166"},{"module": "yanyu", "prompt": "城市治理要下绣花功夫，______的粗放管理已经难以适应发展需要。填入画横线处最恰当的一项是：", "options": ["大而化之", "一丝不苟", "精雕细琢", "细致入微"], "answer": 0, "explanation": "「绣花功夫」与「粗放管理」相对，「大而化之」形容做事马虎笼统，最贴切。细致入微、精雕细琢、一丝不苟均为精细做法。故选A。", "exam": "国考", "diff": 2, "id": "yy-8167"},{"module": "yanyu", "prompt": "个人信息保护需要______，平台不能既当裁判员又当运动员。填入画横线处最恰当的一项是：", "options": ["内部消化", "自我封闭", "暗中操作", "外部监督"], "answer": 3, "explanation": "「不能既当裁判员又当运动员」说明需要外部力量，「外部监督」最贴切。其余三项均与外部制约之意相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8168"},{"module": "yanyu", "prompt": "乡村医生队伍老化、人才难留，补齐这块短板要______，既要待遇留人也要事业留人。填入画横线处最恰当的一项是：", "options": ["单兵突进", "多管齐下", "坐以待毙", "按兵不动"], "answer": 1, "explanation": "「既要……也要……」体现多种手段并用，「多管齐下」最贴切。其余三项均与综合施策之意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8169"},{"module": "yanyu", "prompt": "读书不能急用近利，______的阅读难以沉淀为真正的学养。填入画横线处最恰当的一项是：", "options": ["含英咀华", "融会贯通", "囫囵吞枣", "细嚼慢咽"], "answer": 2, "explanation": "「难以沉淀学养」说明阅读方式粗糙，「囫囵吞枣」比喻理解不求甚解，最贴切。细嚼慢咽、含英咀华、融会贯通均为好的读书方法。故选C。", "exam": "国考", "diff": 2, "id": "yy-8170"},{"module": "yanyu", "prompt": "老旧小区改造，居民意见不一是常态，关键是把协商机制______起来，让大家的事大家商量着办。填入画横线处最恰当的一项是：", "options": ["悬置", "搁浅", "运转", "停摆"], "answer": 2, "explanation": "「让大家的事大家商量着办」需要协商机制正常运作，「运转」最贴切。停摆、悬置、搁浅均与正常运作之意相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8171"},{"module": "yanyu", "prompt": "新能源汽车下乡，充电桩得先行。基础设施______，购买意愿才能跟上。填入画横线处最恰当的一项是：", "options": ["撤除", "闲置", "荒废", "补齐"], "answer": 3, "explanation": "充电桩先行即补齐基础设施短板，「补齐」最贴切。撤除、闲置、荒废均与完善设施之意相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8172"},{"module": "yanyu", "prompt": "历史街区改造要避免过度商业化，留住原住民，才能留住街区的______。填入画横线处最恰当的一项是：", "options": ["冷清感", "空壳化", "同质化", "烟火气"], "answer": 3, "explanation": "「留住原住民」才能保留生活气息，「烟火气」指充满生活气息的氛围，最贴切。其余三项均与生活气息相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8173"},{"module": "yanyu", "prompt": "科技伦理的底线不能失守，相关立法要______，不能等出了事再补救。填入画横线处最恰当的一项是：", "options": ["亡羊补牢", "先行一步", "按兵不动", "事后诸葛"], "answer": 1, "explanation": "「不能等出了事再补救」强调前瞻性，「先行一步」最贴切。按兵不动与主动性相悖；事后诸葛、亡羊补牢正是要避免的情形。故选B。", "exam": "国考", "diff": 2, "id": "yy-8174"},{"module": "yanyu", "prompt": "基层减负要动真格，______文山会海，让干部把精力用在办实事上。填入画横线处最恰当的一项是：", "options": ["助长", "放任", "扩充", "整治"], "answer": 3, "explanation": "「减负」需要整治文山会海。扩充、放任、助长均与减负之意相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8175"},{"module": "yanyu", "prompt": "调研研究切忌______，坐在车里看、隔着玻璃看，发现不了真问题。填入画横线处最恰当的一项是：", "options": ["洞若观火", "明察秋毫", "了如指掌", "走马观花"], "answer": 3, "explanation": "「走马观花」比喻粗略地观察事物，与「坐在车里看、隔着玻璃看」呼应。明察秋毫、洞若观火、了如指掌均形容观察或了解得细致透彻。故选D。", "exam": "国考", "diff": 2, "id": "yy-8176"},{"module": "yanyu", "prompt": "这项改革牵一发而动全身，必须______，先试点再推广。填入画横线处最恰当的一项是：", "options": ["一蹴而就", "横冲直撞", "揠苗助长", "稳扎稳打"], "answer": 3, "explanation": "「先试点再推广」体现稳妥推进，「稳扎稳打」最贴切。横冲直撞形容蛮干；一蹴而就指一步成功；揠苗助长指急于求成。故选D。", "exam": "国考", "diff": 2, "id": "yy-8177"},{"module": "yanyu", "prompt": "面对成绩他从不居功，总是把功劳归于团队，这种______的品格令人敬佩。填入画横线处最恰当的一项是：", "options": ["谦逊低调", "目中无人", "居功自傲", "自吹自擂"], "answer": 0, "explanation": "「从不居功」「功劳归于团队」体现谦逊低调。居功自傲、目中无人、自吹自擂均与文意相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8178"},{"module": "yanyu", "prompt": "一些地方招商______，只看投资额不看匹配度，项目落地后水土不服。填入画横线处最恰当的一项是：", "options": ["精挑细选", "量体裁衣", "饥不择食", "宁缺毋滥"], "answer": 2, "explanation": "「只看投资额不看匹配度」说明招商不加选择，「饥不择食」最贴切。精挑细选、宁缺毋滥、量体裁衣均为审慎做法。故选C。", "exam": "国考", "diff": 2, "id": "yy-8179"},{"module": "yanyu", "prompt": "网络谣言的危害在于______，等到辟谣时，误解往往已经扩散。填入画横线处最恰当的一项是：", "options": ["不动声色", "按部就班", "后发制人", "先声夺人"], "answer": 3, "explanation": "谣言先传播、辟谣后到达，「先声夺人」指抢先造成声势，最贴切。后发制人、不动声色、按部就班均与谣言抢先扩散的语境不符。故选D。", "exam": "国考", "diff": 2, "id": "yy-8180"},{"module": "yanyu", "prompt": "基层工作者要有一双______的眼睛，从群众的柴米油盐中发现真需求。填入画横线处最恰当的一项是：", "options": ["漠然", "迟钝", "敏锐", "麻木"], "answer": 2, "explanation": "「发现真需求」需要敏锐的观察力。迟钝、漠然、麻木均与善于发现相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8181"},{"module": "yanyu", "prompt": "制度设计要______，堵住「钻空子」的空间，让规则真正管用。填入画横线处最恰当的一项是：", "options": ["严密", "疏松", "宽泛", "粗糙"], "answer": 0, "explanation": "「堵住钻空子的空间」需要制度严密。疏松、宽泛、粗糙均与严密性相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8182"},{"module": "yanyu", "prompt": "老一辈工匠______，一件产品反复打磨上百次，才成就了金字招牌。填入画横线处最恰当的一项是：", "options": ["粗制滥造", "得过且过", "敷衍塞责", "精益求精"], "answer": 3, "explanation": "「反复打磨上百次」体现精益求精。敷衍塞责、粗制滥造、得过且过均与认真打磨相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8183"},{"module": "yanyu", "prompt": "应对人口老龄化要______，养老、医疗、养老服务协同推进。填入画横线处最恰当的一项是：", "options": ["各自为政", "零敲碎打", "单兵作战", "系统谋划"], "answer": 3, "explanation": "「协同推进」体现系统性，「系统谋划」最贴切。零敲碎打、单兵作战、各自为政均与协同相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8184"},{"module": "yanyu", "prompt": "一些景区门票经济思维根深蒂固，______，不愿在体验和服务上下功夫。填入画横线处最恰当的一项是：", "options": ["抱残守缺", "与时俱进", "革故鼎新", "推陈出新"], "answer": 0, "explanation": "「思维根深蒂固」「不愿下功夫」体现守旧，「抱残守缺」最贴切。推陈出新、革故鼎新、与时俱进均为创新做法。故选A。", "exam": "国考", "diff": 2, "id": "yy-8185"},{"module": "yanyu", "prompt": "数据安全立法要______，既促进数据流通又守住安全底线。填入画横线处最恰当的一项是：", "options": ["统筹兼顾", "厚此薄彼", "非此即彼", "顾此失彼"], "answer": 0, "explanation": "「既促进流通又守住底线」体现两方面兼顾，「统筹兼顾」最贴切。顾此失彼、厚此薄彼、非此即彼均与兼顾相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8186"},{"module": "yanyu", "prompt": "青年科研人员要敢坐冷板凳，______于热门领域、追逐短期成果，难有大作为。填入画横线处最恰当的一项是：", "options": ["坚守", "扎堆", "深耕", "扎根"], "answer": 1, "explanation": "「敢坐冷板凳」与扎堆热门相对，「扎堆」指一窝蜂聚集，最贴切。深耕、坚守、扎根均为潜心做事的正面表达。故选B。", "exam": "国考", "diff": 2, "id": "yy-8187"},{"module": "yanyu", "prompt": "老旧小区改造资金不能全靠财政，要______社会资本共同参与。填入画横线处最恰当的一项是：", "options": ["排挤", "冻结", "撬动", "封锁"], "answer": 2, "explanation": "「撬动社会资本」为惯用表达，指以少量财政资金带动社会投入。冻结、排挤、封锁均与吸引参与相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8188"},{"module": "yanyu", "prompt": "执法既要有力度也要有温度，处罚不是目的，______才是根本。填入画横线处最恰当的一项是：", "options": ["从重从快", "以罚代管", "一罚了之", "教育引导"], "answer": 3, "explanation": "「处罚不是目的」说明重在教育引导。从重从快、一罚了之、以罚代管均与「温度」相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8189"},{"module": "yanyu", "prompt": "这份规划立足长远，______，为未来十年发展留足了空间和弹性。填入画横线处最恰当的一项是：", "options": ["饮鸩止渴", "鼠目寸光", "急功近利", "高瞻远瞩"], "answer": 3, "explanation": "「立足长远」「为未来十年留足空间」体现远见，「高瞻远瞩」最贴切。鼠目寸光、急功近利、饮鸩止渴均与长远眼光相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8190"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n近年来，我国新能源汽车出口量持续攀升，凭借完整的产业链和电池技术优势，国产品牌在欧洲、东南亚市场占有率不断提高。与此同时，海外建厂、本地化服务也成为头部车企的新选择。", "options": ["我国新能源汽车出口持续增长并加速全球化布局", "我国新能源汽车已垄断全球市场", "海外建厂导致出口量下降", "新能源汽车产业链优势正在丧失"], "answer": 0, "explanation": "文段先讲出口量攀升、市占率提高，再讲海外建厂、本地化服务，核心是出口增长与全球化布局。B项「垄断」过于绝对；C项与文意相反；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8191"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n城市口袋公园虽小，却能在方寸之间见天地。它们利用边角地、闲置地建成，让居民推窗见绿、出门入园。实践证明，小而美的公共空间往往比大广场更贴近日常生活。", "options": ["闲置地不适合改建公园", "大城市不需要大广场", "口袋公园建设成本很高", "口袋公园小而美，贴近居民日常生活"], "answer": 3, "explanation": "文段核心在末句：小而美的公共空间比大广场更贴近日常生活。B项过度引申；C项文段未提成本；D项与文意相反。故选D。", "exam": "国考", "diff": 2, "id": "yy-8192"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n银发经济正在成为新的增长点。老年人在健康管理、文化旅游、终身教育等领域的消费需求快速增长，催生出一批新业态。但供给端的产品和服务仍显单一，适老化改造还有很大空间。", "options": ["适老化改造应当停止", "银发经济增长快，但有效供给仍不足", "老年人消费能力弱", "银发经济已经饱和"], "answer": 1, "explanation": "文段先讲银发经济成为新增长点、需求快速增长，转折后指出供给单一、改造空间大，核心是需求旺而供给不足。B、C、D均与文意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8193"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n无人机送快递、无人车配送正在多地试点。末端物流的智能化改造降低了配送成本，也缓解了人力短缺。不过，其大规模推广还面临空域管理、安全规范等制度性难题。", "options": ["无人机配送已经全面取代人工", "制度难题无法解决", "末端物流成本不降反升", "物流智能化试点成效初显，但推广仍面临制度瓶颈"], "answer": 3, "explanation": "文段先讲智能化试点的成效，转折指出大规模推广面临制度性难题，A项完整概括。B项「全面取代」过于绝对；C项与文意相反；D项「无法解决」无中生有。故选D。", "exam": "国考", "diff": 2, "id": "yy-8194"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n博物馆文创产品频频出圈，考古盲盒、文物冰箱贴让沉睡的文物走进日常生活。文创的本质是让文物承载的文化被看见、被理解，若只追形式新颖而忽视文化内涵，热度终难持久。", "options": ["博物馆文创出圈，但文化内涵才是长久之道", "文创产品只要形式新颖就能成功", "文物冰箱贴是文创的最佳形式", "博物馆文创已经过时"], "answer": 0, "explanation": "文段先讲文创出圈，后强调文化内涵是根本、只追形式难持久，A项概括准确。B项与文意相悖；C项以偏概全；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8195"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n盐碱地是我国重要的后备耕地资源。近年来，科研人员培育出耐盐碱水稻、大豆等品种，配合土壤改良技术，昔日「不毛之地」正变成新粮仓。盐碱地综合利用对保障粮食安全意义重大。", "options": ["盐碱地无法用于农业生产", "盐碱地综合利用技术创新为粮食安全提供新支撑", "我国耕地资源十分充裕", "培育新品种没有必要"], "answer": 1, "explanation": "文段讲盐碱地通过品种培育和土壤改良变成新粮仓，对粮食安全意义重大，A项概括准确。B、C、D均与文意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8196"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n「数字断连」正在成为部分年轻人的选择：主动关闭推送、卸载应用、限定上网时段。他们并非拒绝技术，而是希望在信息洪流中夺回注意力主权，让工具回归工具。", "options": ["信息洪流无法应对", "部分年轻人主动减少网络使用以夺回注意力", "年轻人已经完全脱离互联网", "数字技术有害无益"], "answer": 1, "explanation": "文段讲年轻人主动「数字断连」，目的是夺回注意力主权，A项准确。B项「完全脱离」过于绝对；C项「有害无益」过于绝对，且文段说「并非拒绝技术」；D项与文意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8197"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n社区养老驿站要办得长久，光靠政府补贴不行，还要探索可持续运营模式：引入专业机构、发展互助养老、链接社区商业资源，让驿站既办得起又办得久。", "options": ["养老驿站难以维持", "商业资源与养老无关", "社区养老驿站需要探索可持续运营模式", "政府补贴应当取消"], "answer": 2, "explanation": "文段核心是驿站要探索可持续运营模式，A项准确。B项「取消」过于绝对，文段说「光靠补贴不行」；C项与文意相悖；D项文段强调要链接商业资源。故选C。", "exam": "国考", "diff": 2, "id": "yy-8198"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n古籍数字化让珍贵文献「触手可及」，读者在线即可查阅善本。但数字化不是简单扫描，还要解决著录、标引、检索等问题，让古籍从「看得到」走向「用得好」。", "options": ["在线查阅古籍非常困难", "古籍无需数字化", "古籍数字化就是扫描存档", "古籍数字化要从「看得到」走向「用得好」"], "answer": 3, "explanation": "文段末句是核心：数字化要解决著录、标引、检索问题，从看得到走向用得好。B项与文意相悖；C项与文意相悖；D项与「触手可及」相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8199"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n夜间经济不只是「夜市摊」，还包括夜间文旅演出、24小时书店、博物馆夜场等多元形态。发展夜间经济，既要烟火气也要文化味，还要解决交通、安保等配套问题。", "options": ["夜间经济就是夜市摊", "夜间经济形态多元，需要配套支撑", "夜间经济不宜发展", "配套问题无法解决"], "answer": 1, "explanation": "文段讲夜间经济形态多元，并需要交通、安保等配套，A项准确。B项与文意相悖；C项与文意相悖；D项过于绝对。故选B。", "exam": "国考", "diff": 2, "id": "yy-8200"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n青少年近视率居高不下，与电子屏幕使用时间过长、户外活动不足密切相关。防控近视，「防」大于「治」，保证每天两小时户外活动是最经济有效的办法。", "options": ["近视防控重在预防，户外活动经济有效", "电子屏幕与近视无关", "近视只能靠手术解决", "户外活动对视力无益"], "answer": 0, "explanation": "文段核心是「防」大于「治」，户外活动是最经济有效的办法，A项准确。B项无中生有；C项与文意相悖；D项与文意相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8201"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n预制菜要赢得消费者信任，标准之外还要透明：原料来源、加工过程、物流冷链都应可查询可追溯。信息对称了，疑虑才能消除，行业才能行稳致远。", "options": ["预制菜行业需要全流程透明可追溯", "消费者不应购买预制菜", "标准制定毫无意义", "预制菜行业没有发展前景"], "answer": 0, "explanation": "文段核心是要透明可追溯，消除疑虑。B、C与文意相悖；D项文段强调标准之外还要透明，并非否定标准。故选A。", "exam": "国考", "diff": 2, "id": "yy-8202"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n「以旧换新」政策激发了消费潜力，也带动了回收产业发展。但废旧物资回收体系仍不健全，回收网点少、标准不统一等问题制约着循环经济发展。", "options": ["以旧换新政策应当取消", "回收产业已经成熟", "以旧换新带动循环经济，但回收体系有待完善", "循环经济没有前景"], "answer": 2, "explanation": "文段先讲政策成效，转折指出回收体系不健全，A项准确。B、D与文意相悖；C项与「仍不健全」相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8203"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n乡村文旅要避免同质化竞争，深挖本地独特的自然资源与人文故事，才能形成差异化吸引力。复制粘贴式的「网红村」，热度来得快去得也快。", "options": ["乡村文旅要深挖特色、避免同质化", "自然资源不重要", "同质化竞争有利于发展", "乡村文旅应当复制网红村"], "answer": 0, "explanation": "文段核心是要深挖独特资源、形成差异化，A项准确。B项与文意相悖；C项与文意相悖；D项文段强调自然与人文都重要。故选A。", "exam": "国考", "diff": 2, "id": "yy-8204"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n人工智能辅助诊疗正在基层推广，影像识别、辅助诊断提升了基层医生的诊断效率。但医生的临床经验和人文关怀不可替代，人机协同才是未来方向。", "options": ["基层医生不需要AI", "AI诊疗毫无价值", "AI将全面取代医生", "AI辅助诊疗提升基层效率，人机协同是方向"], "answer": 3, "explanation": "文段先讲AI的成效，后强调医生不可替代、人机协同，A项准确。B项与文意相悖；C项与文意相悖；D项与文意相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8205"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n城市书店不再只是卖书，而是融合了展览、沙龙、咖啡的复合文化空间。转型让书店在电商冲击下找到了新活法，也让阅读有了更多元的打开方式。", "options": ["实体书店已经消亡", "书店转型复合文化空间，找到新的生存方式", "电商对书店没有影响", "复合空间与阅读无关"], "answer": 1, "explanation": "文段讲书店转型复合空间找到新活法，A项准确。B项与文意相悖；C项与文意相悖；D项与「电商冲击下」相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8206"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n长租公寓市场曾因「高收低租」乱象备受质疑。随着监管加强、资金监管账户落地，行业逐步规范。规范化的长租市场，才能同时保护租客与房东的权益。", "options": ["长租公寓行业在监管中走向规范", "资金监管没有必要", "长租公寓乱象无法治理", "监管损害了租客权益"], "answer": 0, "explanation": "文段讲监管加强后行业逐步规范，A项准确。B项与文意相悖；C项与文意相悖；D项与文意相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8207"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n城市更新中，「留改拆」的顺序很有讲究：能留则留、宜改则改、当拆则拆。留住的是城市记忆，改出的是现代功能，拆掉的是安全隐患。顺序背后是治理理念的转变。", "options": ["城市记忆应当全部拆除", "治理理念无需转变", "城市更新应遵循「留改拆」的合理顺序", "城市更新就是大拆大建"], "answer": 2, "explanation": "文段核心是「留改拆」顺序及其背后的治理理念，A项准确。B项与文意相悖；C项与文意相悖；D项与文意相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8208"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n「国潮」兴起不是简单的复古，而是传统文化与当代审美的融合。真正打动消费者的，是设计背后的文化认同。缺乏内涵的贴牌国潮，只能热闹一时。", "options": ["国潮的本质是传统文化与当代审美的融合", "消费者不关心文化内涵", "国潮就是复古", "贴牌国潮能够长久"], "answer": 0, "explanation": "文段核心是国潮的本质与内涵的重要性，A项准确。B项「简单复古」与文意相悖；C项与文意相悖；D项与「只能热闹一时」相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8209"},{"module": "yanyu", "prompt": "这段文字主要说明了什么？\n\n适老化改造不能「一刀切」。不同老人的身体状况、生活习惯差异很大，改造前应充分评估需求，让改造真正贴合老人所需，而不是装了不用的「面子工程」。", "options": ["适老化改造要按需评估、精准施策", "面子工程值得推广", "老人的需求完全相同", "适老化改造应当一刀切"], "answer": 0, "explanation": "文段核心是差异评估、贴合需求，A项准确。B项与文意相悖；C项与文意相悖；D项与文意相悖。故选A。", "exam": "国考", "diff": 2, "id": "yy-8210"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n某市推行「无证明城市」改革，通过数据共享让群众免于开具各类证明。改革以来，累计精简证明事项三百余项，群众办事平均耗时缩短一半以上。", "options": ["数据共享是该市精简证明的重要手段", "该市已完全取消所有证明", "改革未取得任何成效", "群众办事耗时大幅上升"], "answer": 0, "explanation": "文段说通过数据共享让群众免于开证明，精简三百余项、耗时缩短一半，A项正确。B项「完全取消」过于绝对；C项与文意相反；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8211"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n研究显示，规律饮茶与心血管健康存在正相关。茶叶中的茶多酚具有抗氧化作用。但研究者同时提醒，饮茶不能替代药物治疗，浓茶还可能影响睡眠和铁的吸收。", "options": ["饮茶有益健康，但不能替代药物治疗", "浓茶有助于睡眠", "茶多酚有害健康", "饮茶可以治愈心血管疾病"], "answer": 0, "explanation": "文段说饮茶与心血管健康正相关，但不能替代药物治疗，A项正确。B项「治愈」夸大；C项与文意相反；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8212"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n某地推行「田长制」，每一块耕地都有责任人。田长负责巡查、报告违法占用耕地行为，把保护责任落实到人。试点以来，当地违法占用耕地案件明显下降。", "options": ["巡查制度形同虚设", "田长制导致违法案件增加", "耕地保护无人负责", "田长制将耕地保护责任落实到具体责任人"], "answer": 3, "explanation": "文段说每一块耕地都有责任人、责任落实到人，D项正确。A项巡查制度与文意相反；B项田长制是为了减少违法案件，与文意相反；C项无人负责与文意相反。故选D", "exam": "国考", "diff": 2, "id": "yy-8213"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n睡眠不足会影响大脑中类淋巴系统的「排毒」效率，代谢废物清除不畅，进而影响认知功能。长期熬夜者患认知障碍的风险显著高于规律作息者。", "options": ["长期熬夜会升高认知障碍风险", "睡眠越少大脑越健康", "熬夜能促进代谢废物清除", "类淋巴系统与大脑无关"], "answer": 0, "explanation": "文段说长期熬夜者患认知障碍风险显著更高，A项正确。B项与文意相反；C项与文意相反；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8214"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n某平台上线「防沉迷提醒」功能，用户连续使用超过一小时，系统将弹出休息提示并提供护眼模式选项。上线三个月，用户平均单日使用时长有所下降。", "options": ["该平台的防沉迷功能取得了一定效果", "平台反对防沉迷", "用户使用时长大幅上升", "护眼模式会损害视力"], "answer": 0, "explanation": "文段说功能上线三个月后平均单日使用时长有所下降，A项「取得一定效果」正确。B项与文意相反；C项无中生有；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8215"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n海绵城市通过透水铺装、下沉式绿地、雨水花园等设施，让城市像海绵一样吸水、蓄水、渗水、净水，缓解内涝的同时补充地下水。", "options": ["透水铺装无法渗水", "海绵城市与水无关", "海绵城市设施有助于缓解城市内涝", "海绵城市会加剧内涝"], "answer": 2, "explanation": "文段说海绵城市吸水蓄水、缓解内涝，C项正确。A项透水铺装正是为了渗水，与文意相反；B项海绵城市核心就是水的管理与利用，与文意相反；D项海绵城市是为了减轻而非加剧内涝，与文意相反。故选C", "exam": "国考", "diff": 2, "id": "yy-8216"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n某市图书馆推出「信用借阅」服务，市民凭信用分免押金借书。逾期不还将影响信用记录。服务上线后，图书归还率不降反升，市民借阅热情明显提高。", "options": ["免押金服务无人使用", "信用借阅导致逾期增加", "信用借阅服务提升了图书归还率", "市民借阅热情下降"], "answer": 2, "explanation": "文段说归还率不降反升、借阅热情提高，C项正确。A项免押金服务使用踊跃，与文意相反；B项逾期并未增加，与文意相反；D项借阅热情是提高而非下降，与文意相反。故选C", "exam": "国考", "diff": 2, "id": "yy-8217"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n候鸟迁徙依赖沿途的湿地「加油站」。若中途湿地退化，候鸟将因得不到食物补充而难以完成迁徙。保护迁徙路线上的湿地网络，比保护单个湿地更重要。", "options": ["候鸟迁徙不依赖湿地", "湿地退化有利于候鸟迁徙", "单个湿地足以保障迁徙", "候鸟保护需要整条迁徙路线的湿地网络"], "answer": 3, "explanation": "文段末句说保护迁徙路线上的湿地网络比单个湿地更重要，D项正确。A项候鸟迁徙依赖湿地，与文意相反；B项湿地退化不利于候鸟迁徙，与文意相反；C项单个湿地不足以保障迁徙，与文意相反。故选D", "exam": "国考", "diff": 2, "id": "yy-8218"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n某县发展「庭院经济」，引导农户利用房前屋后空地种植特色果蔬、发展手工作坊。小庭院连着大市场，户均年增收数千元。", "options": ["空地只能闲置", "农户收入因此下降", "庭院经济帮助农户实现增收", "庭院经济与市场无关"], "answer": 2, "explanation": "文段说户均年增收数千元、小庭院连着大市场，C项正确。A项空地被有效利用而非闲置，与文意相反；B项农户收入是增加而非下降，与文意相反；D项庭院经济对接市场，与文意相反。故选C", "exam": "国考", "diff": 2, "id": "yy-8219"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n「时间银行」互助养老模式鼓励低龄老人志愿服务高龄老人，服务时长存入「银行」，未来可兑换同等服务。这一模式缓解了养老人手不足，也促进了代际互动。", "options": ["志愿服务时长无法兑换", "时间银行模式有助于缓解养老人手不足", "该模式阻碍代际交流", "时间银行以现金结算"], "answer": 1, "explanation": "文段说时间银行缓解养老人手不足、促进代际互动，B项正确。A项志愿服务时长可以兑换，与文意相反；C项该模式促进而非阻碍代际交流，与文意相反；D项时间银行以服务时长而非现金结算，与文意相反。故选B", "exam": "国考", "diff": 2, "id": "yy-8220"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n某古镇在修缮中坚持「修旧如旧」，使用传统工艺和本地材料，最大限度保留历史风貌。修缮后的古镇游客量回升，原住民也留了下来。", "options": ["原住民全部迁离", "游客量持续下降", "古镇修缮拆除了历史建筑", "「修旧如旧」的修缮保留了古镇历史风貌"], "answer": 3, "explanation": "文段说修缮保留历史风貌、游客回升、原住民留下，D项正确。A项原住民并未迁离，与文意相反；B项游客量回升而非下降，与文意相反；C项修缮保留而非拆除历史建筑，与文意相反。故选D", "exam": "国考", "diff": 2, "id": "yy-8221"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n企业首席数据官制度的推广，让数据资产管理有了专职负责人。试点企业反映，数据孤岛问题明显改善，跨部门数据调用效率显著提升。", "options": ["跨部门调用效率下降", "首席数据官制度改善了企业数据孤岛问题", "数据孤岛问题更加严重", "该制度无人响应"], "answer": 1, "explanation": "文段说试点企业数据孤岛明显改善、调用效率提升，B项正确。A项调用效率是提升而非下降，与文意相反；C项数据孤岛问题明显改善而非加重，与文意相反；D项该制度得到积极响应，与文意相反。故选B", "exam": "国考", "diff": 2, "id": "yy-8222"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n慢行交通系统建设让城市回归以人为本：拓宽人行道、增设自行车道、建设林荫路。某市慢行系统成网后，绿色出行比例提高近十个百分点。", "options": ["绿色出行比例下降", "慢行系统建设提高了绿色出行比例", "人行道被全部取消", "慢行系统与出行方式无关"], "answer": 1, "explanation": "文段说慢行系统成网后绿色出行比例提高近十个百分点，B项正确。A项绿色出行比例是提高而非下降，与文意相反；C项人行道是完善而非取消，与文意相反；D项慢行系统直接影响出行方式，与文意相反。故选B", "exam": "国考", "diff": 2, "id": "yy-8223"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n「反向旅游」兴起，一些非热门城市凭借松弛感和小城烟火气吸引游客。这提示文旅市场：游客不再只追逐知名景区，体验感正成为新标准。", "options": ["游客越来越重视旅游体验感", "游客只认知名景区", "小城市无法发展旅游", "体验感不重要"], "answer": 0, "explanation": "文段说游客不再只追逐知名景区、体验感成为新标准，A项正确。B项与文意相反；C项与文意相反；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8224"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n某市试点「错峰共享停车」，机关单位夜间向周边居民开放闲置车位。试点区域停车难有所缓解，车位利用率明显提高。", "options": ["机关车位全天闲置", "试点没有效果", "共享停车加剧了停车难", "错峰共享停车提高了车位利用率"], "answer": 3, "explanation": "文段说停车难缓解、车位利用率提高，D项正确。A项机关车位错时开放而非全天闲置，与文意相反；B项试点有明显效果，与文意相反；C项共享停车缓解而非加剧停车难，与文意相反。故选D", "exam": "国考", "diff": 2, "id": "yy-8225"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n职业本科教育培养的既是工程师又是实干者。首批职业本科生就业率超过九成，用人单位普遍反映其动手能力强、上手快。", "options": ["职业本科毕业生受到用人单位认可", "职业本科就业率不足五成", "职业本科生动手能力弱", "用人单位普遍不认可"], "answer": 0, "explanation": "文段说就业率超九成、用人单位反映动手能力强，A项正确。B项与文意相反；C项与文意相反；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8226"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n「无废城市」建设并不是不产生固体废物，而是通过源头减量、资源化利用和安全处置，将废物环境影响降至最低。", "options": ["「无废城市」强调废物减量化与资源化", "废物处置无需安全", "资源化利用没有价值", "「无废城市」要求零废物产生"], "answer": 0, "explanation": "文段说不产生废物而是减量、资源化、安全处置，A项正确。B项与「并不是不产生」相悖；C项与「安全处置」相悖；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8227"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n某地推行「乡村规划师」制度，专业人才驻村指导村庄建设。规划师们帮村庄梳理空间、保护风貌、盘活资源，一批闲置农房变身民宿和工坊。", "options": ["乡村规划师导致资源闲置", "村庄建设无需规划", "农房只能继续空置", "乡村规划师助力村庄盘活闲置资源"], "answer": 3, "explanation": "文段说规划师帮村庄盘活资源、闲置农房变身民宿工坊，D项正确。A项规划师盘活而非闲置资源，与文意相反；B项村庄建设正需要规划，与文意相反；C项农房被盘活而非空置，与文意相反。故选D", "exam": "国考", "diff": 2, "id": "yy-8228"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n「一刻钟便民生活圈」让居民步行一刻钟即可满足买菜、理发、维修等日常需求。试点社区的生活便利度满意度明显提升，小店经济也随之活跃。", "options": ["便民生活圈提升了居民生活便利度", "小店经济因此萎缩", "居民满意度下降", "生活圈内无法满足日常需求"], "answer": 0, "explanation": "文段说便利度满意度提升、小店经济活跃，A项正确。B项与文意相反；C项与文意相反；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8229"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n红树林是海岸带的「绿色长城」，能消浪护岸、净化水质、固碳储碳。近年来多地开展红树林修复，修复区域的海岸生态功能明显恢复。", "options": ["修复工程毫无作用", "红树林破坏海岸生态", "红树林具有消浪护岸等生态功能", "红树林没有固碳能力"], "answer": 2, "explanation": "文段说红树林消浪护岸、净化水质、固碳储碳，C项正确。A项修复工程作用显著，与文意相反；B项红树林维护而非破坏海岸生态，与文意相反；D项红树林有很强固碳能力，与文意相反。故选C", "exam": "国考", "diff": 2, "id": "yy-8230"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n「共享用工」让淡旺季不同企业之间实现员工余缺调剂。旺季企业获得人力，淡季企业降低成本，员工获得稳定收入，实现多方共赢。", "options": ["共享用工只对企业有利", "员工收入因此不稳定", "共享用工实现了企业间的员工余缺调剂", "共享用工导致员工失业"], "answer": 2, "explanation": "文段说共享用工实现余缺调剂、多方共赢，C项正确。A项共享用工对企业和员工都有利，与文意相反；B项员工获得稳定收入，与文意相反；D项共享用工是调剂而非失业，与文意相反。故选C", "exam": "国考", "diff": 2, "id": "yy-8231"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n某市将「免罚清单」纳入执法实践，对首次轻微违法且及时改正的市场主体不予处罚。清单实施后，市场主体合规意识不降反升，营商环境满意度提高。", "options": ["免罚清单兼顾了执法温度与合规引导", "营商环境满意度下降", "市场主体合规意识下降", "免罚清单导致违法激增"], "answer": 0, "explanation": "文段说合规意识不降反升、营商环境满意度提高，A项正确。B项与文意相反；C项与文意相反；D项与文意相反。故选A。", "exam": "国考", "diff": 2, "id": "yy-8232"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n「城市漫步」带火了老街区，游客按路线走访历史建筑、探访小店。这股热潮若要持续，离不开对街区商业生态的保护，避免租金上涨挤走原有小店。", "options": ["原有小店应当迁离", "城市漫步的持续发展需要保护街区商业生态", "城市漫步损害了历史建筑", "租金上涨有利于热潮持续"], "answer": 1, "explanation": "文段说热潮持续离不开商业生态保护、避免租金挤走小店，B项正确。A项原有小店被保留而非迁离，与文意相反；C项城市漫步并未损害历史建筑，与文意相反；D项租金上涨会挤走小店、不利于热潮持续，与文意相反。故选B", "exam": "国考", "diff": 2, "id": "yy-8233"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n「智慧农业」让种地有了「科技范」：无人机植保、水肥一体化、物联网监测在大田推广。试点农场化肥农药用量下降，产量不降反升。", "options": ["物联网与农业无关", "智慧农业导致产量下降", "智慧农业实现了化肥农药减量且不减产", "化肥用量大幅上升"], "answer": 2, "explanation": "文段说化肥农药用量下降、产量不降反升，C项正确。A项智慧农业以物联网为支撑，与文意相反；B项产量上升而非下降，与文意相反；D项化肥用量是下降而非上升，与文意相反。故选C", "exam": "国考", "diff": 2, "id": "yy-8234"},{"module": "yanyu", "prompt": "根据这段文字，下列说法正确的是：\n\n「银龄教师」计划招募退休教师赴乡村学校支教。老教师们带去了经验，也带去了对教育的热忱，受援学校的教学质量有所提升。", "options": ["受援学校质量下降", "银龄教师计划提升了受援学校教学质量", "该计划已经终止", "退休教师无法胜任支教"], "answer": 1, "explanation": "文段说受援学校教学质量有所提升，B项正确。A项受援学校质量是提升而非下降，与文意相反；C项计划仍在推进，与文意相反；D项退休教师经验丰富、能够胜任支教，与文意相反。故选B", "exam": "国考", "diff": 2, "id": "yy-8235"},{"module": "yanyu", "prompt": "政务服务「好差评」制度让群众来______，倒逼窗口服务提质增效。填入画横线处最恰当的一项是：", "options": ["回避", "服从", "评判", "观望"], "answer": 2, "explanation": "「让群众来评判」与「好差评」制度呼应。服从、观望、回避均与评价机制之意相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8236"},{"module": "yanyu", "prompt": "文化遗产保护要与当代生活______，让文物在合理利用中焕发生机。填入画横线处最恰当的一项是：", "options": ["脱节", "相融", "割裂", "对立"], "answer": 1, "explanation": "「焕发生机」需要与当代生活相融。割裂、对立、脱节均与合理利用之意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8237"},{"module": "yanyu", "prompt": "防汛工作宁可十防九空，也不能______，预案要落实到最后一公里。填入画横线处最恰当的一项是：", "options": ["滴水不漏", "失防万一", "严阵以待", "万无一失"], "answer": 1, "explanation": "「宁可十防九空，也不能失防万一」为惯用表述，指不能在万一的情况上失守。万无一失、滴水不漏、严阵以待均为周密防备之意，与句意相悖。故选B。", "exam": "国考", "diff": 2, "id": "yy-8238"},{"module": "yanyu", "prompt": "老旧小区改造要问需于民，改造方案不能由设计单位______，居民的意见要充分吸纳。填入画横线处最恰当的一项是：", "options": ["闭门造车", "入户走访", "集思广益", "实地调研"], "answer": 0, "explanation": "「不能由设计单位闭门造车」与「充分吸纳居民意见」呼应。实地调研、入户走访、集思广益均为正确做法。故选A。", "exam": "国考", "diff": 2, "id": "yy-8239"},{"module": "yanyu", "prompt": "青年要敢于到基层去、到一线去，在______中经风雨、长才干。填入画横线处最恰当的一项是：", "options": ["养尊处优", "坐享其成", "袖手旁观", "摸爬滚打"], "answer": 3, "explanation": "「经风雨、长才干」需要在实践中磨炼，「摸爬滚打」最贴切。养尊处优、坐享其成、袖手旁观均与磨炼相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8240"},{"module": "yanyu", "prompt": "营商环境好不好，企业用脚投票。哪里的服务好、效率高，企业就会在哪里______。填入画横线处最恰当的一项是：", "options": ["打退堂鼓", "望而却步", "绕道而行", "落地生根"], "answer": 3, "explanation": "「用脚投票」指企业选择环境好的地方，「落地生根」最贴切。望而却步、打退堂鼓、绕道而行均与选择入驻相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8241"},{"module": "yanyu", "prompt": "基层治理数字化转型不能______，平台建起来了，服务跟上了才算数。填入画横线处最恰当的一项是：", "options": ["重形轻效", "注重实效", "务求实效", "行之有效"], "answer": 0, "explanation": "「平台建起来了，服务跟上了才算数」批评只重形式，「重形轻效」最贴切。注重实效、务求实效、行之有效均为正面表达。故选A。", "exam": "国考", "diff": 2, "id": "yy-8242"},{"module": "yanyu", "prompt": "粮食安全是「国之大者」，耕地红线要______，任何人都不得逾越。填入画横线处最恰当的一项是：", "options": ["逐步放开", "视同儿戏", "严防死守", "随意调整"], "answer": 2, "explanation": "耕地红线要严防死守，与「不得逾越」呼应。随意调整、逐步放开、视同儿戏均与红线意识相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8243"},{"module": "yanyu", "prompt": "传统村落保护不能只留房子不留人，要让人______、让村有活力。填入画横线处最恰当的一项是：", "options": ["进不来", "迁出去", "回得来", "留不住"], "answer": 2, "explanation": "「只留房子不留人」的反面是让人回得来，与「村有活力」呼应。进不来、留不住、迁出去均与文意相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8244"},{"module": "yanyu", "prompt": "科技小院把课堂搬到田间地头，学生在______中把论文写在大地上。填入画横线处最恰当的一项是：", "options": ["闭门造车", "坐而论道", "纸上谈兵", "躬耕实践"], "answer": 3, "explanation": "「把论文写在大地上」强调实践，「躬耕实践」最贴切。纸上谈兵、闭门造车、坐而论道均与实践相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8245"},{"module": "yanyu", "prompt": "政务新媒体不能重建设轻运营，账号开了就要______，别让服务窗口成摆设。填入画横线处最恰当的一项是：", "options": ["随意发布", "停止更新", "一关了之", "用心维护"], "answer": 3, "explanation": "「别让服务窗口成摆设」需要用心维护。停止更新、随意发布、一关了之均与运营好账号相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8246"},{"module": "yanyu", "prompt": "老字号焕新不能丢了自己的根，要在传承与创新之间找到______。填入画横线处最恰当的一项是：", "options": ["分界线", "终点站", "平衡点", "对立面"], "answer": 2, "explanation": "传承与创新之间要找「平衡点」。对立面、分界线、终点站均与兼顾传承创新之意相悖。故选C。", "exam": "国考", "diff": 2, "id": "yy-8247"},{"module": "yanyu", "prompt": "防汛物资储备要______，宁可备而不用，不可用而无备。填入画横线处最恰当的一项是：", "options": ["亡羊补牢", "未雨绸缪", "临时抱佛脚", "临阵磨枪"], "answer": 1, "explanation": "「宁可备而不用，不可用而无备」强调提前准备，「未雨绸缪」最贴切。临阵磨枪、亡羊补牢、临时抱佛脚均为事后或临时应对。故选B。", "exam": "国考", "diff": 2, "id": "yy-8248"},{"module": "yanyu", "prompt": "社区治理要激发居民参与热情，让大家从旁观者变为______。填入画横线处最恰当的一项是：", "options": ["评论员", "局外人", "旁观者", "参与者"], "answer": 3, "explanation": "「从旁观者变为参与者」体现激发参与热情。旁观者、局外人与「从旁观者」重复且无转变；评论员不贴切。故选D。", "exam": "国考", "diff": 2, "id": "yy-8249"},{"module": "yanyu", "prompt": "乡村教师队伍建设既要待遇留人，也要感情留人、事业留人，______才能稳定队伍。填入画横线处最恰当的一项是：", "options": ["无所作为", "听之任之", "单打独斗", "多措并举"], "answer": 3, "explanation": "「既要……也要……」体现多种措施并用，「多措并举」最贴切。单打独斗、无所作为、听之任之均与综合施策相悖。故选D。", "exam": "国考", "diff": 2, "id": "yy-8250"},{"id": "yy-8301", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：基层治理既要靠制度约束，也要靠情感浸润，二者________、缺一不可。", "options": ["相辅相成", "南辕北辙", "此消彼长", "针锋相对"], "answer": 0, "explanation": "「相辅相成」指两者互相配合、互相促成，与「缺一不可」呼应，符合制度与情感并重的关系。「南辕北辙」指行动与目的相反，「此消彼长」指一方减弱另一方增强，「针锋相对」指互相对立，均与文意相悖。故选A。", "diff": 2},{"id": "yy-8302", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：科研评价不能只看论文数量，要________，把成果的实际贡献作为重要衡量标准。", "options": ["正本清源", "急功近利", "实事求是", "标新立异"], "answer": 2, "explanation": "「实事求是」指按照实际情况办事，与前文「不能只看论文数量」形成对照，强调看实际贡献。「正本清源」指从根本上整顿清理，「急功近利」是贬义词与语境矛盾，「标新立异」指提出新奇主张。故选C。", "diff": 2},{"id": "yy-8303", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：传统文化不是博物馆里的陈列品，它需要在创新中________，在传承中发展。", "options": ["固步自封", "生生不息", "墨守成规", "一成不变"], "answer": 1, "explanation": "「生生不息」指不断生长、不断发展，与「在传承中发展」衔接自然，体现文化生命力。「固步自封」「墨守成规」「一成不变」都是贬义，指保守不进取，与「创新」「发展」矛盾。故选B。", "diff": 2},{"id": "yy-8304", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：生态修复工程不能________，要尊重自然规律，给自然留出恢复的时间。", "options": ["拔苗助长", "精雕细琢", "因地制宜", "循序渐进"], "answer": 0, "explanation": "「拔苗助长」比喻违反事物发展规律急于求成，与「尊重自然规律」「留出恢复时间」构成反向呼应。「精雕细琢」「因地制宜」「循序渐进」均为褒义的做事方法，与语境不符。故选A。", "diff": 2},{"id": "yy-8305", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：面对突发舆情，有关部门应当及时________信息，主动回应关切，而不是遮遮掩掩。", "options": ["公开", "封锁", "编造", "模糊"], "answer": 0, "explanation": "与「主动回应关切」和「而不是遮遮掩掩」对应，应填「公开」。「封锁」「编造」「模糊」都与及时回应、主动沟通的正确做法相悖，且「编造」明显不当。故选A。", "diff": 2},{"id": "yy-8306", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：青年人要有________的锐气，也要有________的定力，既敢闯敢试，又脚踏实地。", "options": ["敢为人先、持之以恒", "随波逐流、半途而废", "好高骛远、虎头蛇尾", "标新立异、朝三暮四"], "answer": 0, "explanation": "第一空与「锐气」「敢闯敢试」对应，应填「敢为人先」；第二空与「定力」「脚踏实地」对应，应填「持之以恒」。其余三项均为贬义，与语境矛盾。故选A。", "diff": 2},{"id": "yy-8307", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：乡村振兴趣不能________地照搬城市模式，要立足乡土实际，走自己的路。", "options": ["亦步亦趋", "独辟蹊径", "量体裁衣", "有的放矢"], "answer": 0, "explanation": "「亦步亦趋」比喻自己没有主张，事事模仿别人，与「照搬城市模式」对应，且与「立足乡土实际，走自己的路」形成转折。「独辟蹊径」「量体裁衣」「有的放矢」均为褒义，不合语境。故选A。", "diff": 2},{"id": "yy-8308", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：执法既要有力度，也要有温度，在________违法的同时________当事人的合法权益。", "options": ["惩处、保障", "鼓励、剥夺", "纵容、侵犯", "忽视、维护"], "answer": 0, "explanation": "「惩处」与「违法」搭配且对应「力度」，「保障」与「合法权益」搭配且对应「温度」，逻辑通顺。B、C、D三项的搭配均与执法语境矛盾。故选A。", "diff": 2},{"id": "yy-8309", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：数字经济浪潮________，唯有主动学习、更新知识，才能不被时代淘汰。", "options": ["势不可挡", "戛然而止", "停滞不前", "半途而废"], "answer": 0, "explanation": "「势不可挡」指来势迅猛不可阻挡，与「浪潮」搭配恰当，且与「唯有主动学习」的紧迫感呼应。「戛然而止」「停滞不前」「半途而废」与语境相反。故选A。", "diff": 2},{"id": "yy-8310", "module": "yanyu", "prompt": "依次填入下列横线处的词语，最恰当的一组是：调查研究要________，深入田间地头，听真话、察实情，不能走马观花。", "options": ["沉下身子", "高高在上", "闭门造车", "纸上谈兵"], "answer": 0, "explanation": "「沉下身子」与「深入田间地头」「听真话、察实情」一致，与「走马观花」相反。「高高在上」「闭门造车」「纸上谈兵」都是要否定的做法，与「要」字后的正面要求矛盾。故选A。", "diff": 2},{"id": "yy-8311", "module": "yanyu", "prompt": "这段文字主要说明了什么？近年来，随着北斗系统全球组网成功，其应用已从交通运输、农林渔业逐步拓展到电力、金融、通信等关键领域，「北斗+」正在成为数字经济新的增长点。", "options": ["北斗系统的应用范围不断扩大", "北斗系统的组网过程十分艰难", "数字经济已经取代传统产业", "北斗系统只用于军事领域"], "answer": 0, "explanation": "文段先指出北斗应用从交通、渔业拓展到电力、金融、通信等领域，再以「北斗+」成为新增长点收尾，核心是应用范围不断扩大。B项组网过程未展开，C项「取代」无中生有，D项与「全球组网、民用领域」矛盾。故选A。", "diff": 2},{"id": "yy-8312", "module": "yanyu", "prompt": "作者意在强调：城市治理不能只靠政府「单打独斗」，要搭建平台让居民、社会组织、企业共同参与，形成共建共治共享的格局。", "options": ["政府应放弃城市治理责任", "多元主体参与是城市治理的方向", "企业是城市治理的唯一主体", "居民参与会增加治理成本"], "answer": 1, "explanation": "文段核心句是「要搭建平台让居民、社会组织、企业共同参与」，落脚点是「共建共治共享」，即多元主体参与是方向。A项「放弃责任」曲解文意，C项「唯一主体」与「多元」矛盾，D项无中生有。故选B。", "diff": 2},{"id": "yy-8313", "module": "yanyu", "prompt": "下列说法与文意相符的是：有研究团队发现，适度饮用绿茶有助于延缓认知衰退，但前提是长期规律饮用，偶尔饮用并无明显效果。", "options": ["绿茶能治愈老年痴呆", "偶尔饮用绿茶效果明显", "长期规律饮用绿茶可能延缓认知衰退", "绿茶是唯一延缓认知衰退的饮品"], "answer": 2, "explanation": "C项是对「适度饮用绿茶有助于延缓认知衰退，前提是长期规律饮用」的同义转述。A项「治愈」夸大，B项与「偶尔饮用并无明显效果」矛盾，D项「唯一」无中生有。故选C。", "diff": 2},{"id": "yy-8314", "module": "yanyu", "prompt": "最适合做这段文字标题的是：一部手机，一个直播间，山货出山、非遗出圈。如今，越来越多的新农人用短视频记录乡村生活，把家乡的特产卖向全国，数字技术正在重塑乡村的经济版图。", "options": ["短视频：乡村经济的新引擎", "乡村生活的日常记录", "非遗传承的困境与出路", "手机行业的竞争格局"], "answer": 0, "explanation": "文段围绕「新农人用短视频卖特产、数字技术重塑乡村经济」展开，「短视频：乡村经济的新引擎」既点明主体又概括主旨。B项只谈记录未涉及经济价值，C项「困境」无中生有，D项偏离主题。故选A。", "diff": 2},{"id": "yy-8315", "module": "yanyu", "prompt": "这段文字意在说明：垃圾分类看似是小事，实则牵动着城市治理的方方面面。从投放、收集到运输、处理，每个环节都需要精细化管理，也需要每位居民的理解与配合。", "options": ["垃圾分类是城市治理中的系统工程", "居民不配合垃圾分类", "垃圾运输环节最为重要", "垃圾分类已经全面完成"], "answer": 0, "explanation": "文段先说垃圾分类「牵动着城市治理的方方面面」，再列举各环节都需要精细化管理，意在说明它是系统工程。B项与「需要每位居民的理解与配合」的期待语气矛盾，C项「最为重要」无比较，D项与实际不符。故选A。", "diff": 2},{"id": "yy-8316", "module": "yanyu", "prompt": "下列说法与文意不符的是：候鸟迁徙是自然界最壮观的景象之一。研究表明，候鸟能够利用地球磁场、太阳位置和地标等多种线索导航，其中磁场感应被认为是长距离迁徙的「罗盘」。", "options": ["候鸟迁徙可以利用地球磁场导航", "磁场感应可能是候鸟长距离迁徙的重要依据", "候鸟只依靠地标完成迁徙", "候鸟迁徙可借助多种线索"], "answer": 2, "explanation": "文段明确说候鸟利用磁场、太阳、地标「等多种线索」导航，C项「只依靠地标」与文意不符。A、B、D三项均能在原文找到依据。故选C。", "diff": 2},{"id": "yy-8317", "module": "yanyu", "prompt": "将下列句子排成语意连贯的一段话，顺序最恰当的是：①这种坚持看似笨拙②实际上是对品质的敬畏③老字号的手艺人几十年只做一道工序④也是品牌长盛不衰的根基", "options": ["③①②④", "①③②④", "③②①④", "①②③④"], "answer": 0, "explanation": "③引出话题「老字号手艺人只做一道工序」；①「这种坚持」承接③；②「实际上」转折递进，解释坚持的内涵；④「也是」并列递进收尾，升华到品牌根基。故选A。", "diff": 2},{"id": "yy-8318", "module": "yanyu", "prompt": "将下列句子排成语意连贯的一段话，顺序最恰当的是：①数据是新的生产要素②但数据的采集与使用必须有边界③它正在深刻改变生产生活方式④否则就会侵犯个人隐私", "options": ["①③②④", "③①②④", "①②③④", "②①③④"], "answer": 0, "explanation": "①提出观点「数据是新的生产要素」；③「它」承接①说明其影响；②「但」转折指出要有边界；④「否则」承接②说明后果。故选A。", "diff": 2},{"id": "yy-8319", "module": "yanyu", "prompt": "填入横线处最恰当的是：读书的意义，不仅在于获取知识，________。一个热爱阅读的人，往往能在纷繁的信息中保持清醒的判断。", "options": ["更在于培养独立思考的能力", "而且读书要花很多时间", "但是书店越来越少了", "所以知识就是力量"], "answer": 0, "explanation": "横线前「不仅在于获取知识」提示后文要用「更在于」递进，且与后文「保持清醒的判断」呼应，「培养独立思考的能力」衔接最紧密。B、C两项偏离话题，D项「所以」逻辑不通。故选A。", "diff": 2},{"id": "yy-8320", "module": "yanyu", "prompt": "填入横线处最恰当的是：基层是政策落实的「最后一公里」，________。只有打通这个环节，好政策才能真正惠及群众。", "options": ["也是矛盾问题最容易聚集的地方", "基层干部都很辛苦", "政策制定要科学民主", "群众的需求多种多样"], "answer": 0, "explanation": "横线处与「最后一公里」呼应，并引出「打通这个环节」的结论，「也是矛盾问题最容易聚集的地方」既承接上文又为下文铺垫。B、C、D三项均无法与「打通环节」形成因果衔接。故选A。", "diff": 2},{"id": "yy-8321", "module": "yanyu", "prompt": "填入横线处最恰当的是：传统村落是农耕文明的活化石，________。保护传统村落，就是保护我们的乡愁和文脉。", "options": ["承载着丰富的历史文化信息", "但是交通十分不便", "旅游开发要适度", "村民生活需要改善"], "answer": 0, "explanation": "横线处需要解释为什么传统村落是「活化石」、为什么保护它就是保护乡愁文脉，「承载着丰富的历史文化信息」承上启下。B、C、D三项都偏离了「保护价值」这一主线。故选A。", "diff": 2},{"id": "yy-8322", "module": "yanyu", "prompt": "填入横线处最恰当的是：科技创新离不开宽容失败的氛围。________，才能让科研人员敢闯「无人区」，勇攀高峰。", "options": ["只有允许试错、包容失败", "如果失败就会被追责", "因为成功属于少数人", "所以科研评价要看论文"], "answer": 0, "explanation": "横线后「才能」提示前面要用「只有」构成必要条件句，「允许试错、包容失败」与「宽容失败的氛围」一致。B项与文意相反，C、D两项偏离话题。故选A。", "diff": 2},{"id": "yy-8323", "module": "yanyu", "prompt": "填入横线处最恰当的是：志愿服务是社会文明程度的重要标志。________，让「我为人人、人人为我」蔚然成风。", "options": ["广泛开展志愿服务活动", "志愿服务没有回报", "要强制所有人参加", "志愿服务已经过时"], "answer": 0, "explanation": "横线处需要与「让『我为人人、人人为我』蔚然成风」构成手段与结果的呼应，「广泛开展志愿服务活动」最贴切。B项消极，C项「强制」错误，D项与「重要标志」矛盾。故选A。", "diff": 2},{"id": "yy-8324", "module": "yanyu", "prompt": "填入横线处最恰当的是：文化遗产保护要与当代生活相连。________，文物才能真正「活」起来。", "options": ["只有融入百姓的日常生活", "只要锁进博物馆保险柜", "即使无人问津也没关系", "但是保护第一利用第二"], "answer": 0, "explanation": "横线后「才能」提示「只有」引导条件，「融入百姓的日常生活」与「与当代生活相连」「活起来」呼应。B项与「活起来」矛盾，C项消极，D项偏离话题。故选A。", "diff": 2},{"id": "yy-8325", "module": "yanyu", "prompt": "填入横线处最恰当的是：粮食安全是「国之大者」。________，把中国人的饭碗牢牢端在自己手中。", "options": ["只有守住耕地红线、提升产能", "因为粮食价格持续上涨", "所以粮食可以大量进口", "但是种粮效益比较低下"], "answer": 0, "explanation": "横线后「把中国人的饭碗牢牢端在自己手中」是目的，前面需要「只有」引导的措施，「守住耕地红线、提升产能」正是保障粮食安全的根本途径。B、C、D三项均不能与目的句衔接。故选A。", "diff": 2},{"id": "yy-8336", "module": "yanyu", "prompt": "根据语境，横线处的句子最恰当的是：城市不是钢筋水泥的简单堆砌，________。一座有温度的城市，会让每一个生活其中的人感受到归属感。", "options": ["而是由生活在其间的人赋予温度的有机体", "而是建筑物数量的简单相加", "但是交通拥堵问题依然严重", "所以城市规划要超前"], "answer": 0, "explanation": "横线前「不是……简单堆砌」提示后文用「而是」构成否定与肯定的呼应，且与后文「有温度的城市」呼应，「由人赋予温度的有机体」衔接最自然。B项与「不是简单堆砌」重复且无推进，C、D两项偏离话题。故选A。", "diff": 2},{"id": "yy-8337", "module": "yanyu", "prompt": "根据语境，横线处的句子最恰当的是：数字经济时代，数据是重要的生产要素。________，才能既促进发展又保护权益。", "options": ["只有划清数据使用的法律边界", "只要数据足够多就行", "即使侵犯隐私也无所谓", "所以数据不能流通使用"], "answer": 0, "explanation": "横线后「才能既促进发展又保护权益」提示「只有」引导条件，「划清法律边界」正是兼顾发展与保护的举措。B项片面，C项与「保护权益」矛盾，D项与「促进发展」矛盾。故选A。", "diff": 2},{"id": "yy-8338", "module": "yanyu", "prompt": "根据语境，横线处的句子最恰当的是：青少年沉迷短视频的问题值得关注。________，学校和家庭应共同引导，帮助他们建立健康的用网习惯。", "options": ["沉迷不仅影响视力，还会挤占学习和运动的时间", "短视频平台都是有害的", "青少年不应该接触任何电子产品", "家长应该没收孩子的手机"], "answer": 0, "explanation": "横线处需要说明沉迷的危害，引出「共同引导」的必要性，A项危害表述客观且与后文衔接自然。B、C、D三项都过于绝对或偏激，不符合「引导」的语境。故选A。", "diff": 2},{"id": "yy-8339", "module": "yanyu", "prompt": "根据语境，横线处的句子最恰当的是：老字号要焕发新生机，不能只靠情怀。________，才能在激烈的市场竞争中站稳脚跟。", "options": ["只有在守正的基础上不断创新", "只要打广告就够了", "即使产品过时也没关系", "所以要把老字号全部关闭"], "answer": 0, "explanation": "横线后「才能」提示「只有」引导条件，「守正创新」正是老字号焕发新生的正确路径，与「不能只靠情怀」呼应。B项片面，C项消极，D项荒谬。故选A。", "diff": 2},{"id": "yy-8340", "module": "yanyu", "prompt": "根据语境，横线处的句子最恰当的是：阅读是成本最低的自我增值方式。________，日积月累，终会遇见更好的自己。", "options": ["每天哪怕只读十页书", "读书要挑最贵的买", "不读书也能成功", "所以图书馆应该关闭"], "answer": 0, "explanation": "横线后「日积月累」提示前面应是可持续的小行动，「每天哪怕只读十页书」与「成本最低」「日积月累」呼应。B、C、D三项均偏离或违背文意。故选A。", "diff": 2},{"id": "yy-8341", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某市推出「免罚清单」，对首次轻微违法且及时纠正的市场主体不予处罚。这一做法________，激发了市场活力。", "options": ["体现了处罚与教育相结合的原则", "说明违法不需要承担责任", "意味着执法可以随意变通", "导致市场秩序混乱"], "answer": 0, "explanation": "「免罚清单」针对轻微违法、及时纠正的情形，体现「处罚与教育相结合」的行政执法原则，与「激发市场活力」因果顺畅。B、C、D三项都是对这一做法的误读。故选A。", "diff": 2},{"id": "yy-8342", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某地推行「办不成事」反映窗口，专门受理群众办事遇到的疑难事项。窗口虽小，________，赢得了群众好评。", "options": ["却打通了便民服务的「最后一公里」", "却增加了群众的办事成本", "却让群众办事更难了", "却形同虚设"], "answer": 0, "explanation": "「窗口虽小」与「却」构成转折，「打通最后一公里」与「赢得群众好评」因果一致。B、C、D三项都与「赢得好评」矛盾。故选A。", "diff": 2},{"id": "yy-8343", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某县干部驻村后，先花一个月时间走访全村农户，摸清每家的困难与需求，再制定帮扶计划。这种________的工作方法，值得推广。", "options": ["先调研后决策", "先决策后调研", "只调研不决策", "不调研不决策"], "answer": 0, "explanation": "「先走访摸清情况，再制定计划」正是「先调研后决策」的体现。B项顺序颠倒，C、D两项曲解文意。故选A。", "diff": 2},{"id": "yy-8344", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某市图书馆推出「深夜书房」，延长开放至午夜，为备考人群和夜班读者提供便利。这一举措________，受到年轻人欢迎。", "options": ["回应了不同群体的阅读需求", "浪费了公共资源", "干扰了周边居民休息", "降低了图书馆品位"], "answer": 0, "explanation": "「深夜书房」服务备考人群和夜班读者，正是「回应不同群体阅读需求」的体现，与「受欢迎」一致。B、C、D三项均为负面评价，与「受到欢迎」矛盾。故选A。", "diff": 2},{"id": "yy-8345", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某地把「红白喜事简办」写进村规民约，村民议事会全程监督操办。一段时间下来，________，乡风明显好转。", "options": ["人情负担轻了、攀比之风淡了", "人情负担更重了", "宴席规模更大了", "村民负担增加了"], "answer": 0, "explanation": "「简办」与「监督」的结果应是负担减轻、风气好转，A项与「乡风明显好转」因果一致。B、C、D三项都与「简办」的效果相反。故选A。", "diff": 2},{"id": "yy-8346", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某市在政务大厅推行「好差评」制度，群众办完事可以现场评价，评价结果与窗口人员考核挂钩。________，服务质量持续提升。", "options": ["倒逼工作人员改进服务", "增加了群众负担", "让评价流于形式", "使办事流程更复杂"], "answer": 0, "explanation": "「评价与考核挂钩」的结果是「倒逼改进服务」，与「服务质量持续提升」因果一致。B、C、D三项都与「持续提升」矛盾。故选A。", "diff": 2},{"id": "yy-8347", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某镇推广「积分制」管理，村民参与环境整治、志愿服务可以攒积分，积分能兑换生活用品。小积分________，乡村治理有了新抓手。", "options": ["撬动了乡村治理的大格局", "增加了村民的负担", "是形式主义的表现", "让村民失去了兴趣"], "answer": 0, "explanation": "「小积分」与「大格局」形成以小见大的呼应，与「新抓手」一致。B、C、D三项都是负面评价，与「治理有新抓手」矛盾。故选A。", "diff": 2},{"id": "yy-8348", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某市试行「错峰上下班」，鼓励企事业单位灵活安排通勤时间。一段时间后，________，早晚高峰的交通压力得到缓解。", "options": ["部分市民的通勤时间错开了", "所有市民都开车出行了", "公共交通全部停运了", "道路更加拥堵了"], "answer": 0, "explanation": "「错峰上下班」的直接效果是「通勤时间错开」，与「交通压力缓解」因果一致。B、C、D三项都与「压力缓解」矛盾。故选A。", "diff": 2},{"id": "yy-8349", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某社区组织「邻里节」活动，居民一起包饺子、猜灯谜、演节目。活动虽小，________，陌生邻居渐渐熟络起来。", "options": ["却拉近了邻里之间的距离", "却增加了社区的开支", "却让居民感到厌烦", "却制造了新的矛盾"], "answer": 0, "explanation": "「活动虽小」与「却」转折，「拉近邻里距离」与「渐渐熟络」一致。B、C、D三项都与「熟络起来」矛盾。故选A。", "diff": 2},{"id": "yy-8350", "module": "yanyu", "prompt": "填入下文横线处最恰当的是：某地推行「田长制」，每块耕地都有责任人巡田护地。耕地有了「管家」，________，乱占耕地现象得到遏制。", "options": ["违法占用行为早发现早制止", "耕地面积大幅减少", "粮食产量逐年下降", "土地撂荒更加严重"], "answer": 0, "explanation": "「田长制」的效果是「早发现早制止」，与「乱占现象得到遏制」因果一致。B、C、D三项都是负面结果，与「遏制」矛盾。故选A。", "diff": 2}]);
